"use client";

import React, { useState } from "react";
import { Product, WorkInProgress, IncomingStock, SupplierStockLot } from "@/types";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Loader2, Upload, ImageIcon, Info } from "lucide-react";
import { cn } from "@/lib/utils";
import { isRollBag } from "@/lib/services";
import { supabase } from "@/lib/supabase";
import imageCompression from "browser-image-compression";

type BagsInventoryCardsProps = {
    products: Product[];
    inventoryMap: Map<string, { quantity: number; updatedAt?: string }>;
    saleAllocationMap: Map<string, { bags: number; meters: number }>;
    wipMap: Map<string, WorkInProgress[]>;
    supplierStockMap: Map<string, number>;
    supplierStockLotsMap: Map<string, SupplierStockLot[]>;
    incomingMap: Map<string, { total: number; items: IncomingStock[] }>;
    onDetail: (product: Product) => void;
    onRefetch: () => void;
};

export function BagsInventoryCards({
    products,
    inventoryMap,
    saleAllocationMap,
    wipMap,
    supplierStockMap,
    supplierStockLotsMap,
    incomingMap,
    onDetail,
    onRefetch
}: BagsInventoryCardsProps): React.ReactElement {
    if (products.length === 0) {
        return (
            <div className="text-center py-12 text-muted-foreground bg-slate-50 rounded-lg border border-dashed">
                該当する商品がありません
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
            {products.map(product => (
                <ProductCard
                    key={product.id}
                    product={product}
                    inventoryMap={inventoryMap}
                    saleAllocationMap={saleAllocationMap}
                    wipMap={wipMap}
                    supplierStockMap={supplierStockMap}
                    supplierStockLotsMap={supplierStockLotsMap}
                    incomingMap={incomingMap}
                    onDetail={onDetail}
                    onRefetch={onRefetch}
                />
            ))}
        </div>
    );
}

type ProductCardProps = {
    product: Product;
    inventoryMap: Map<string, { quantity: number; updatedAt?: string }>;
    saleAllocationMap: Map<string, { bags: number; meters: number }>;
    wipMap: Map<string, WorkInProgress[]>;
    supplierStockMap: Map<string, number>;
    supplierStockLotsMap: Map<string, SupplierStockLot[]>;
    incomingMap: Map<string, { total: number; items: IncomingStock[] }>;
    onDetail: (product: Product) => void;
    onRefetch: () => void;
};

function ProductCard({
    product,
    inventoryMap,
    saleAllocationMap,
    wipMap,
    supplierStockMap,
    supplierStockLotsMap,
    incomingMap,
    onDetail,
    onRefetch
}: ProductCardProps) {
    const [isHovered, setIsHovered] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [uploading, setUploading] = useState(false);

    // 在庫計算
    const stockInfo = inventoryMap.get(product.id) || { quantity: 0 };
    const currentStock = stockInfo.quantity;
    const allocation = saleAllocationMap.get(product.id) || { bags: 0, meters: 0 };
    const wipList = wipMap.get(product.id) || [];
    const wipQuantity = wipList.reduce((sum, item) => sum + item.quantity, 0);
    const supplier = supplierStockMap.get(product.id) || 0;
    const supplierLots = supplierStockLotsMap?.get(product.id) || [];
    const incoming = incomingMap.get(product.id);

    const isRoll = product.shape && isRollBag(product.shape);

    // 有効在庫
    const availableStock = Math.max(0, currentStock - (isRoll ? allocation.meters : allocation.bags));

    // ステータス判定 (直送先在庫と廃盤は除外)
    const isOutOfStock = (product.status !== 'direct_delivery' && product.status !== 'discontinued' && product.status !== 'on_sale_break') && (availableStock <= 0);
    const isLowStock = (product.status !== 'direct_delivery' && product.status !== 'discontinued') && (
        isRoll
            ? availableStock > 0 && availableStock < 50
            : availableStock > 0 && availableStock < 100
    );
    const hasAllocation = allocation.bags > 0;

    // 画像アップロード処理
    const handleDrop = async (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);

        if (uploading) return;

        const file = e.dataTransfer.files?.[0];
        if (file && file.type.startsWith("image/")) {
            await processImageUpload(file);
        }
    };

    const processImageUpload = async (file: File) => {
        setUploading(true);
        try {
            // 圧縮
            const compressedFile = await imageCompression(file, {
                maxSizeMB: 0.2,
                maxWidthOrHeight: 800,
                useWebWorker: true,
                fileType: "image/webp"
            });

            // Storageへアップロード
            const fileName = `products/${product.sku || product.id}_${Date.now()}.webp`;
            const { data, error: uploadError } = await supabase.storage
                .from("product-images")
                .upload(fileName, compressedFile, {
                    contentType: "image/webp",
                    upsert: false
                });

            if (uploadError) throw uploadError;

            // URL取得
            const { data: publicUrlData } = supabase.storage
                .from("product-images")
                .getPublicUrl(data.path);

            const imageUrl = publicUrlData.publicUrl;

            // 商品更新API呼び出し
            const response = await fetch("/api/products", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    id: product.id,
                    imageUrl: imageUrl
                })
            });

            if (!response.ok) throw new Error("Failed to update product");

            onRefetch();
        } catch (error) {
            console.error("Upload failed:", error);
            alert("画像のアップロードに失敗しました");
        } finally {
            setUploading(false);
        }
    };

    return (
        <Card
            className={cn(
                "overflow-hidden transition-all duration-200 hover:shadow-md h-full flex flex-col",
                isDragging && "ring-2 ring-blue-500 ring-offset-2 scale-[1.02]",
                isOutOfStock ? "border-red-200 bg-red-50/10" : "hover:border-primary/50"
            )}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
            onDragLeave={() => setIsDragging(false)}
            onDrop={handleDrop}
            onClick={() => onDetail(product)}
        >
            {/* 画像エリア - クリックで詳細でもいいが、フォームを開くのが無難 */}
            <div className="relative aspect-[4/3] bg-slate-100 group">
                {product.imageUrl ? (
                    <img
                        src={product.imageUrl}
                        alt={product.name}
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                    />
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-muted-foreground bg-slate-50">
                        <ImageIcon className="h-10 w-10 mb-2 opacity-20" />
                        <span className="text-xs opacity-40">No Image</span>
                        <span className="text-[10px] opacity-30 mt-1">Drop image here</span>
                    </div>
                )}

                {/* ステータスバッジ (画像の上に重ねる) */}
                <div className="absolute top-2 left-2 flex flex-col gap-1">
                    {isOutOfStock ? (
                        <Badge variant="destructive" className="shadow-sm">欠品</Badge>
                    ) : isLowStock ? (
                        <Badge variant="outline" className="bg-amber-100 text-amber-700 border-amber-300 shadow-sm">低在庫</Badge>
                    ) : product.status === 'plate_removal_scheduled' ? (
                        <Badge variant="outline" className="border-amber-400 text-amber-600 bg-amber-50 shadow-sm">落版予定</Badge>
                    ) : product.status === 'plate_removed' ? (
                        <Badge variant="outline" className="border-purple-400 text-purple-600 bg-purple-50 shadow-sm">落版</Badge>
                    ) : product.status === 'direct_delivery' ? (
                        <Badge variant="outline" className="border-blue-400 text-blue-600 bg-blue-50 shadow-sm">直送先在庫</Badge>
                    ) : product.status === 'on_sale_break' ? (
                        <Badge variant="outline" className="border-yellow-400 text-yellow-600 bg-yellow-50 shadow-sm">販売中断</Badge>
                    ) : product.status === 'discontinued' ? (
                        <Badge variant="outline" className="border-gray-400 text-gray-500 bg-gray-50 shadow-sm">廃盤</Badge>
                    ) : null}
                    {hasAllocation && (
                        <Badge className="bg-blue-600 shadow-sm text-[10px] px-1 h-5">特売引当中</Badge>
                    )}
                </div>

                {product.discontinuedDate && product.status !== 'active' && (
                    <div className="absolute bottom-2 left-2 bg-black/60 text-white text-[10px] px-1.5 py-0.5 rounded backdrop-blur-sm">
                        {new Date(product.discontinuedDate).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}
                        {(product.status === 'plate_removed' || product.status === 'plate_removal_scheduled') ? '落版' : '廃盤'}
                    </div>
                )}

                {/* オーバーレイアクション（ホバー時 or ドラッグ時） */}
                {(isHovered || isDragging || uploading) && (
                    <div className={cn(
                        "absolute inset-0 bg-black/40 flex flex-col items-center justify-center transition-opacity duration-200",
                        isDragging ? "opacity-100 bg-blue-500/20 backdrop-blur-sm" : "opacity-0 group-hover:opacity-100"
                    )}>
                        {uploading ? (
                            <Loader2 className="h-8 w-8 text-white animate-spin" />
                        ) : isDragging ? (
                            <div className="text-white font-bold flex flex-col items-center animate-pulse">
                                <Upload className="h-10 w-10 mb-2" />
                                <span>画像を追加・更新</span>
                            </div>
                        ) : (
                            <div className="flex gap-2">
                                <Button
                                    size="sm"
                                    variant="secondary"
                                    className="h-8"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onDetail(product);
                                    }}
                                >
                                    <Info className="h-4 w-4 mr-1" /> 詳細
                                </Button>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <CardContent className="p-3 flex-1 flex flex-col gap-2">
                <div>
                    <div className="flex items-start justify-between gap-2 mb-1">
                        <h3 className="font-medium text-sm line-clamp-2 leading-tight min-h-[2.5em]" title={`${product.name} (${product.weight}kg)`}>
                            {product.name} ({product.weight}kg)
                        </h3>
                    </div>
                    <div className="flex flex-wrap gap-1 mb-2">
                        {product.variety && <Badge variant="outline" className="text-[10px] px-1 h-4 bg-amber-50 text-amber-700 border-amber-200">{product.variety}</Badge>}
                        {product.origin && <Badge variant="outline" className="text-[10px] px-1 h-4 bg-green-50 text-green-700 border-green-200">{product.origin}</Badge>}
                        <Badge variant="outline" className="text-[10px] px-1 h-4">{product.weight}kg</Badge>
                    </div>
                </div>

                <div className="mt-auto pt-2 border-t border-dashed">
                    <div className="flex justify-between items-end">
                        <div className="text-[10px] text-muted-foreground flex flex-col gap-0.5">
                            <div>SKU: {product.sku}</div>
                            {wipList && wipList.length > 0 && (
                                <div className="text-purple-600 font-medium">
                                    仕掛中: {wipQuantity.toLocaleString()}{isRoll ? 'm' : '枚'}
                                    <div className="flex flex-col gap-0.5 mt-0.5 opacity-80 font-normal">
                                        {wipList.map((item, i) => (
                                            <div key={item.id}>
                                                {item.expectedCompletion ?
                                                    (() => {
                                                        const d = new Date(item.expectedCompletion);
                                                        const month = d.getMonth() + 1;
                                                        if (item.termType === 'early') return `${month}月上旬: `;
                                                        if (item.termType === 'mid') return `${month}月中旬: `;
                                                        if (item.termType === 'late') return `${month}月下旬: `;
                                                        return `${d.toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}: `;
                                                    })()
                                                    : '未定: '}
                                                {item.quantity.toLocaleString()}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* メーカー在庫の表示 */}
                            {supplier > 0 && (
                                <div className="text-orange-600 mt-2 text-[10px] text-right">
                                    メーカー: {supplier.toLocaleString()}{isRoll ? 'm' : '枚'}
                                    <div className="flex flex-col gap-0.5 mt-0.5 opacity-80 font-normal">
                                        {supplierLots.map((lot, i) => {
                                            const now = new Date();
                                            const arrival = new Date(lot.stockDate);
                                            const monthsElapsed = (now.getFullYear() - arrival.getFullYear()) * 12 + now.getMonth() - arrival.getMonth();
                                            const isLongTerm = monthsElapsed >= 5;

                                            return (
                                                <div key={i} className="flex justify-end items-center gap-1">
                                                    {isLongTerm && (
                                                        <Badge variant="destructive" className="h-4 px-1 text-[8px] whitespace-nowrap">長期在庫</Badge>
                                                    )}
                                                    <div className="text-[10px] leading-tight whitespace-nowrap">
                                                        {new Date(lot.stockDate).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}: {lot.quantity.toLocaleString()}
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            )}
                        </div>
                        <div className="text-right">
                            <div className={cn(
                                "text-lg font-bold leading-none",
                                isOutOfStock ? "text-red-600" : isLowStock ? "text-amber-600" : "text-slate-700"
                            )}>
                                {availableStock.toLocaleString()}
                                <span className="text-xs font-normal text-muted-foreground ml-0.5">
                                    {isRoll ? 'm' : '枚'}
                                </span>
                            </div>
                            {hasAllocation && (
                                <div className="text-[10px] text-blue-600">
                                    引当: {allocation.bags.toLocaleString()}枚
                                </div>
                            )}

                            {/* 入荷予定の表示 */}
                            {incoming && incoming.total > 0 && (
                                <div
                                    className="text-[10px] text-emerald-600 font-medium mt-1"
                                >
                                    入荷予定: {incoming.total.toLocaleString()}{isRoll ? 'm' : '枚'}
                                    <div className="flex flex-col gap-0.5 mt-0.5 opacity-80 font-normal">
                                        {incoming.items.map((item, index) => (
                                            <div key={index}>
                                                {new Date(item.expectedDate).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}: {item.quantity.toLocaleString()}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* 未設定の場合はクリックで開けるように "+" アイコンやテキストを出すことも検討可能だが一旦非表示 */}
                        </div>
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

"use client";

import React, { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Dialog, DialogContent, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import {
    Check,
    Plus,
    Pencil,
    Trash2,
    Download,
    X,
    LineChart,
    Package,
} from "lucide-react";
import {
    getPitch,
    calculateStockStatus,
} from "@/lib/services";
import { useCart } from "@/contexts/cart-context";
import type { Product, WorkInProgress, IncomingStock } from "@/types";
import { SupplierStockDialog } from "@/components/inventory/supplier-stock-dialog";
import { WIPDialog } from "@/components/inventory/wip-dialog";
import { StockAdjustmentDialog } from "@/components/inventory/stock-adjustment-dialog";
import { StockAllocationDialog } from "@/components/inventory/stock-allocation-dialog";
import { ProductStatusDialog } from "@/components/inventory/product-status-dialog";
import type { SaleEvent } from "@/hooks/use-sale-events";
import type { SupplierStockLot } from "@/types";
import { useAppSettings } from "@/hooks/use-masters";



export type BagsInventoryTableProps = {
    products: Product[];
    inventoryMap: Map<string, { quantity: number; updatedAt?: string }>;
    saleAllocationMap: Map<string, { bags: number; meters: number }>;
    wipMap: Map<string, WorkInProgress[]>;
    supplierStockMap: Map<string, number>;
    supplierStockLotsMap: Map<string, SupplierStockLot[]>;
    incomingMap: Map<string, { total: number; items: IncomingStock[] }>;
    saleEvents: SaleEvent[];
    onEdit: (product: Product) => void;
    onIncomingStockClick: (product: Product) => void;
    onAnalyze?: (product: Product) => void;
    onRefetch: () => void;
};

export function BagsInventoryTable({ products, inventoryMap, saleAllocationMap, wipMap, supplierStockMap, supplierStockLotsMap, incomingMap, saleEvents, onEdit, onIncomingStockClick, onAnalyze, onRefetch }: BagsInventoryTableProps): React.ReactElement {
    const [editSupplierStock, setEditSupplierStock] = useState<Product | null>(null);
    const [editWIP, setEditWIP] = useState<Product | null>(null);
    const [viewAllocation, setViewAllocation] = useState<Product | null>(null);
    const [adjustStock, setAdjustStock] = useState<Product | null>(null);
    const [editStatusProduct, setEditStatusProduct] = useState<Product | null>(null);
    const { addToCart, items } = useCart();
    const { settings } = useAppSettings();

    // 画像拡大用ステート
    const [selectedImage, setSelectedImage] = useState<{ url: string; alt: string; name: string } | null>(null);

    return (
        <Card>
            <CardHeader>
                <CardTitle>米袋在庫状況 ({products.length}件)</CardTitle>
            </CardHeader>
            <CardContent>
                {products.length === 0 ? (
                    <div className="text-center py-8 text-muted-foreground">
                        該当する商品がありません
                    </div>
                ) : (
                    <Table wrapperClassName="h-[calc(100vh-280px)] overflow-auto border rounded-md">
                        <TableHeader className="bg-background shadow-[0_1px_3px_rgba(0,0,0,0.1)]">
                            <TableRow>
                                <TableHead className="w-[60px] sticky top-0 left-0 z-50 bg-background bg-clip-padding border-r shadow-sm">画像</TableHead>
                                <TableHead className="w-[180px] sticky top-0 md:left-[60px] z-40 md:z-50 bg-background bg-clip-padding md:border-r md:shadow-sm">商品情報</TableHead>
                                <TableHead className="w-[120px] sticky top-0 md:left-[240px] z-40 md:z-50 bg-background bg-clip-padding md:border-l md:shadow-[2px_2px_5px_-1px_rgba(0,0,0,0.1)]">スペック</TableHead>
                                <TableHead className="text-right sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">現在庫</TableHead>
                                <TableHead className="text-right sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">特売引当</TableHead>
                                <TableHead className="text-right sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">有効在庫</TableHead>
                                <TableHead className="text-right sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">入荷予定</TableHead>
                                <TableHead className="text-right sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">メーカー在庫</TableHead>
                                <TableHead className="text-right sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">仕掛中</TableHead>
                                <TableHead className="text-center sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">在庫状況</TableHead>
                                <TableHead className="text-center sticky top-0 z-40 bg-background bg-clip-padding shadow-sm">全体状況</TableHead>
                                <TableHead className="w-[140px] sticky top-0 z-40 bg-background bg-clip-padding shadow-sm text-left pl-5">発注</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {products.map((product) => {
                                const inventoryItem = inventoryMap.get(product.id) || { quantity: 0 };
                                const currentStock = inventoryItem.quantity;
                                const updatedAt = inventoryItem.updatedAt;

                                const allocation = saleAllocationMap.get(product.id) || { bags: 0, meters: 0 };
                                const incoming = incomingMap.get(product.id);
                                const wipList = wipMap.get(product.id) || [];

                                // ロットがある場合はロットの合計を優先表示（DB同期ズレ対策）
                                const supplierStockLots = supplierStockLotsMap?.get(product.id) || [];
                                const supplierStockFromLots = supplierStockLots.length > 0
                                    ? supplierStockLots.reduce((sum, lot) => sum + lot.quantity, 0)
                                    : (supplierStockMap.get(product.id) || 0);
                                const supplierStock = supplierStockFromLots;

                                const {
                                    availableStock,
                                    currentBags,
                                    availableBags,
                                    isOutOfStock,
                                    isLowStock,
                                    isRoll,
                                } = calculateStockStatus(product, currentStock, allocation, settings);

                                const hasAllocation = allocation.bags > 0;
                                const isInCart = items.some(item => item.product.id === product.id);

                                return (
                                    <TableRow key={product.id} className={cn("group", isOutOfStock && "bg-red-50 bg-opacity-50")}>
                                        <TableCell className={cn(
                                            "sticky left-0 z-10 transition-colors border-r",
                                            isOutOfStock ? "bg-red-50" : "bg-background group-hover:bg-muted/50"
                                        )}>
                                            {product.imageUrl ? (
                                                <div
                                                    className="cursor-pointer hover:opacity-80 transition-opacity"
                                                    onClick={() => setSelectedImage({ url: product.imageUrl!, alt: product.name, name: product.name })}
                                                >
                                                    <img
                                                        src={product.imageUrl}
                                                        alt={product.name}
                                                        className="w-12 h-12 object-cover rounded border"
                                                    />
                                                </div>
                                            ) : (
                                                <div className="w-12 h-12 bg-gray-100 rounded border flex items-center justify-center">
                                                    <Package className="h-5 w-5 text-gray-400" />
                                                </div>
                                            )}
                                        </TableCell>
                                        <TableCell className={cn(
                                            "md:sticky md:left-[60px] z-0 md:z-10 transition-colors md:border-r",
                                            isOutOfStock ? "bg-red-50" : "bg-background group-hover:bg-muted/50"
                                        )}>
                                            <div className="max-w-[180px]">
                                                <div className="font-medium truncate" title={product.name}>{product.name}</div>
                                                <div className="text-sm text-gray-500 truncate">受注№: {product.sku || '-'}</div>
                                                {product.productCode && <div className="text-sm text-gray-500 truncate">商品コード: {product.productCode}</div>}
                                                <div className="text-xs text-gray-400 truncate">JAN: {product.janCode || '-'}</div>
                                            </div>
                                        </TableCell>
                                        <TableCell className={cn(
                                            "md:sticky md:left-[240px] z-0 md:z-10 md:shadow-[2px_0_5px_-1px_rgba(0,0,0,0.1)] transition-colors",
                                            isOutOfStock ? "bg-red-50" : "bg-background group-hover:bg-muted/50"
                                        )}>
                                            <div className="text-sm">
                                                <span className="font-medium">{product.weight}kg</span> / {product.shape}
                                                {isRoll && (
                                                    <>
                                                        <div className="text-xs text-blue-600 mt-1">
                                                            ピッチ: {getPitch(product.weight || 0)}mm
                                                        </div>
                                                        <div className="text-xs text-green-600">
                                                            1巻: {product.metersPerRoll || 400}m
                                                        </div>
                                                    </>
                                                )}
                                            </div>
                                        </TableCell>
                                        <TableCell
                                            className="text-right cursor-pointer hover:bg-muted/50 transition-colors group relative"
                                            onClick={() => setAdjustStock(product)}
                                        >
                                            {isRoll ? (
                                                <>
                                                    <div className="font-bold text-lg flex items-center justify-end gap-1">
                                                        {currentStock.toLocaleString()}m
                                                        <Pencil className="h-3 w-3 text-muted-foreground opacity-0 group-hover:opacity-100" />
                                                    </div>
                                                    <div className="text-xs text-muted-foreground float-right">約{currentBags.toLocaleString()}枚</div>
                                                </>
                                            ) : (
                                                <div className="font-bold text-lg flex items-center justify-end gap-1">
                                                    {currentStock.toLocaleString()}枚
                                                    <Pencil className="h-3 w-3 text-muted-foreground opacity-0 group-hover:opacity-100" />
                                                </div>
                                            )}
                                            {updatedAt && (
                                                <div className="text-[10px] text-gray-400 clear-both pt-1">
                                                    {new Date(updatedAt).toLocaleDateString()}{" "}
                                                    {new Date(updatedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </div>
                                            )}
                                        </TableCell>
                                        <TableCell
                                            className={cn("text-right", hasAllocation && "cursor-pointer hover:bg-blue-50 transition-colors")}
                                            onClick={() => hasAllocation && setViewAllocation(product)}
                                        >
                                            {hasAllocation ? (
                                                <div className="text-blue-600">
                                                    <div className="font-medium underline decoration-dotted underline-offset-4">
                                                        {allocation.bags.toLocaleString()}
                                                        <span className="text-xs ml-0.5">枚</span>
                                                    </div>
                                                    <div className="flex flex-col gap-0.5 mt-0.5">
                                                        {saleEvents
                                                            .flatMap(event => {
                                                                const item = event.items.find(i => i.productId === product.id);
                                                                if (item && item.allocatedQuantity > 0 && (event.status === 'active' || event.status === 'upcoming')) {
                                                                    return [{
                                                                        date: event.dates[0],
                                                                        client: event.clientName,
                                                                        quantity: item.allocatedQuantity
                                                                    }];
                                                                }
                                                                return [];
                                                            })
                                                            .sort((a, b) => (a.date || "").localeCompare(b.date || ""))
                                                            .map((alloc, index) => (
                                                                <div key={index} className="text-[10px] leading-tight opacity-80 whitespace-nowrap">
                                                                    {alloc.date ? (new Date(alloc.date).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })) : '-'}:{" "}
                                                                    {alloc.client}: {alloc.quantity.toLocaleString()}
                                                                </div>
                                                            ))
                                                        }
                                                    </div>
                                                </div>
                                            ) : (
                                                <span className="text-muted-foreground">-</span>
                                            )}
                                        </TableCell>
                                        <TableCell className="text-right">
                                            {isRoll ? (
                                                <>
                                                    <div className={cn(
                                                        "font-bold text-lg",
                                                        isOutOfStock && "text-red-600",
                                                        isLowStock && "text-amber-600"
                                                    )}>
                                                        {availableStock.toLocaleString()}m
                                                    </div>
                                                    <div className={cn(
                                                        "text-xs float-right",
                                                        isOutOfStock && "text-red-500",
                                                        isLowStock && "text-amber-500"
                                                    )}>
                                                        約{availableBags.toLocaleString()}枚
                                                    </div>
                                                </>
                                            ) : (
                                                <div className={cn(
                                                    "font-bold text-lg",
                                                    isOutOfStock && "text-red-600",
                                                    isLowStock && "text-amber-600"
                                                )}>
                                                    {availableStock.toLocaleString()}枚
                                                </div>
                                            )}
                                        </TableCell>
                                        <TableCell
                                            className="text-right cursor-pointer hover:bg-muted/50 transition-colors group"
                                            onClick={() => onIncomingStockClick(product)}
                                        >
                                            {incoming && incoming.total > 0 ? (
                                                <div className="text-emerald-600">
                                                    <div className="font-medium underline decoration-dotted underline-offset-4">
                                                        {incoming.total.toLocaleString()}{isRoll ? 'm' : '枚'}
                                                    </div>
                                                    <div className="flex flex-col gap-0.5 mt-0.5">
                                                        {incoming.items.map((item, index) => (
                                                            <div key={index} className="text-[10px] leading-tight opacity-80 whitespace-nowrap overflow-hidden text-ellipsis max-w-[150px]" title={item.note || ''}>
                                                                {new Date(item.expectedDate).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}: {item.quantity.toLocaleString()}
                                                                {item.note && <span className="ml-1 text-[9px] text-emerald-700">({item.note})</span>}
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex items-center justify-end">
                                                    <span className="text-muted-foreground group-hover:hidden">-</span>
                                                    <Plus className="h-3 w-3 text-muted-foreground hidden group-hover:block" />
                                                </div>
                                            )}
                                        </TableCell>
                                        <TableCell
                                            className="text-right cursor-pointer hover:bg-muted/50 transition-colors group"
                                            onClick={() => setEditSupplierStock(product)}
                                        >
                                            {supplierStock > 0 ? (
                                                <div className="text-orange-600">
                                                    <div className="font-medium underline decoration-dotted underline-offset-4">
                                                        {supplierStock.toLocaleString()}{isRoll ? 'm' : '枚'}
                                                    </div>
                                                    <div className="flex flex-col gap-0.5 mt-0.5">
                                                        {supplierStockLots.map((lot, i) => {
                                                            const now = new Date();
                                                            const arrival = new Date(lot.stockDate);
                                                            const monthsElapsed = (now.getFullYear() - arrival.getFullYear()) * 12 + now.getMonth() - arrival.getMonth();
                                                            const isLongTerm = monthsElapsed >= 5;

                                                            return (
                                                                <div key={i} className="flex justify-end items-center gap-1">
                                                                    {isLongTerm && (
                                                                        <Badge variant="destructive" className="h-4 px-1 text-[8px] whitespace-nowrap">長期在庫</Badge>
                                                                    )}
                                                                    <div className="text-[10px] leading-tight opacity-80 whitespace-nowrap">
                                                                        {new Date(lot.stockDate).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}: {lot.quantity.toLocaleString()}
                                                                    </div>
                                                                </div>
                                                            );
                                                        })}
                                                    </div>
                                                    {supplierStockLots.length === 0 && (
                                                        <div className="text-[10px] mt-0.5 text-right">メーカー</div>
                                                    )}
                                                </div>
                                            ) : (
                                                <div className="flex items-center justify-end">
                                                    <span className="text-muted-foreground group-hover:hidden">-</span>
                                                    <Pencil className="h-3 w-3 text-muted-foreground hidden group-hover:block" />
                                                </div>
                                            )}
                                        </TableCell>

                                        <TableCell
                                            className="text-right cursor-pointer hover:bg-muted/50 transition-colors group"
                                            onClick={() => setEditWIP(product)}
                                        >
                                            {wipList && wipList.length > 0 ? (
                                                <div className="text-purple-600">
                                                    <div className="font-medium text-base">
                                                        {wipList.reduce((sum, item) => sum + item.quantity, 0).toLocaleString()}
                                                        <span className="text-xs ml-0.5">{isRoll ? 'm' : '枚'}</span>
                                                    </div>
                                                    <div className="flex flex-col gap-0.5 mt-0.5">
                                                        {wipList.map((item, i) => (
                                                            <div key={item.id} className="text-[10px] leading-tight opacity-80 whitespace-nowrap">
                                                                {item.expectedCompletion ?
                                                                    (() => {
                                                                        const d = new Date(item.expectedCompletion);
                                                                        const month = d.getMonth() + 1;
                                                                        if (item.termType === 'early') return `${month}月上旬: `;
                                                                        if (item.termType === 'mid') return `${month}月中旬: `;
                                                                        if (item.termType === 'late') return `${month}月下旬: `;
                                                                        return `${d.toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}: `;
                                                                    })()
                                                                    : '未定: '}
                                                                {item.quantity.toLocaleString()}
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex items-center justify-end">
                                                    <span className="text-muted-foreground group-hover:hidden">-</span>
                                                    <Plus className="h-3 w-3 text-muted-foreground hidden group-hover:block" />
                                                </div>
                                            )}
                                        </TableCell>

                                        {/* 在庫状況 (Inventory Status) */}
                                        <TableCell
                                            className="text-center cursor-pointer hover:bg-muted/50 transition-colors group"
                                            onClick={() => setEditStatusProduct(product)}
                                        >
                                            <div className="flex flex-col items-center gap-1 relative">
                                                {isOutOfStock ? (
                                                    <Badge variant="destructive" className="group-hover:opacity-80 transition-opacity whitespace-nowrap">
                                                        {product.statusOverride === 'out_of_stock' ? '欠品 (手動)' : '欠品'}
                                                    </Badge>
                                                ) : isLowStock ? (
                                                    <Badge variant="outline" className="border-amber-500 text-amber-600 group-hover:bg-amber-50 transition-colors whitespace-nowrap">
                                                        {product.statusOverride === 'low_stock' ? '低在庫 (手動)' : '低在庫'}
                                                    </Badge>
                                                ) : hasAllocation ? (
                                                    <Badge variant="outline" className="border-blue-500 text-blue-600 group-hover:bg-blue-50 transition-colors whitespace-nowrap">引当中</Badge>
                                                ) : (
                                                    <Badge variant="outline" className="border-green-500 text-green-600 group-hover:bg-green-50 transition-colors whitespace-nowrap">正常</Badge>
                                                )}
                                            </div>
                                        </TableCell>

                                        {/* 全体状況 (Overall Status) */}
                                        <TableCell
                                            className="text-center cursor-pointer hover:bg-muted/50 transition-colors group"
                                            onClick={() => setEditStatusProduct(product)}
                                        >
                                            <div className="flex flex-col items-center gap-1 relative">
                                                {product.status === 'wip_check' ? (
                                                    <Badge variant="outline" className="border-indigo-400 text-indigo-600 bg-indigo-50 group-hover:bg-indigo-100 transition-colors whitespace-nowrap">仕掛確認</Badge>
                                                ) : product.status === 'spot' ? (
                                                    <Badge variant="outline" className="border-emerald-400 text-emerald-600 bg-emerald-50 group-hover:bg-emerald-100 transition-colors whitespace-nowrap">スポット</Badge>
                                                ) : product.status === 'plate_removal_scheduled' ? (
                                                    <Badge variant="outline" className="border-amber-400 text-amber-600 bg-amber-50 group-hover:bg-amber-100 transition-colors whitespace-nowrap">落版予定</Badge>
                                                ) : product.status === 'plate_removed' ? (
                                                    <Badge variant="outline" className="border-purple-400 text-purple-600 bg-purple-50 group-hover:bg-purple-100 transition-colors whitespace-nowrap">落版</Badge>
                                                ) : product.status === 'direct_delivery' ? (
                                                    <Badge variant="outline" className="border-blue-400 text-blue-600 bg-blue-50 group-hover:bg-blue-100 transition-colors whitespace-nowrap">直送先在庫</Badge>
                                                ) : product.status === 'on_sale_break' ? (
                                                    <Badge variant="outline" className="border-yellow-400 text-yellow-600 bg-yellow-50 group-hover:bg-yellow-100 transition-colors whitespace-nowrap">販売中断</Badge>
                                                ) : product.status === 'discontinued' ? (
                                                    <Badge variant="outline" className="border-gray-400 text-gray-500 bg-gray-50 group-hover:bg-gray-100 transition-colors whitespace-nowrap">廃盤</Badge>
                                                ) : (
                                                    <span className="text-muted-foreground group-hover:hidden">-</span>
                                                )}

                                                {product.discontinuedDate && product.status !== 'active' && (
                                                    <div className="text-[10px] text-muted-foreground whitespace-nowrap">
                                                        {new Date(product.discontinuedDate).toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })}
                                                        {(product.status === 'plate_removed' || product.status === 'plate_removal_scheduled') ? '落版' : '廃盤'}
                                                    </div>
                                                )}
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex items-center gap-1">
                                                <Button
                                                    size="sm"
                                                    variant={isInCart ? "secondary" : "outline"}
                                                    onClick={() => addToCart(product, 0)}
                                                    disabled={isOutOfStock}
                                                    className="gap-1"
                                                >
                                                    {isInCart ? <Check className="h-3 w-3" /> : <Plus className="h-3 w-3" />}
                                                </Button>
                                                <Button size="sm" variant="ghost" onClick={(e) => { e.stopPropagation(); onAnalyze?.(product); }} title="在庫分析">
                                                    <LineChart className="h-3 w-3 text-blue-600" />
                                                </Button>
                                                <Button size="sm" variant="outline" onClick={(e) => { e.stopPropagation(); onEdit(product); }} title="編集">
                                                    <Pencil className="h-4 w-4 mr-2" />
                                                    編集
                                                </Button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>
                )}
            </CardContent>

            <StockAdjustmentDialog
                product={adjustStock}
                open={!!adjustStock}
                onOpenChange={(open) => !open && setAdjustStock(null)}
                currentStock={adjustStock ? (inventoryMap.get(adjustStock.id)?.quantity || 0) : 0}
                supplierStock={adjustStock ? (supplierStockMap.get(adjustStock.id) || 0) : 0}
                wipItems={adjustStock ? (wipMap.get(adjustStock.id) || []) : []}
                saleAllocations={adjustStock ? saleAllocationMap.get(adjustStock.id) : undefined}
                onSuccess={onRefetch}
            />

            <SupplierStockDialog
                product={editSupplierStock}
                open={!!editSupplierStock}
                onOpenChange={(open) => !open && setEditSupplierStock(null)}
                currentStock={editSupplierStock ? (supplierStockMap.get(editSupplierStock.id) || 0) : 0}
                onSuccess={onRefetch}
            />

            <WIPDialog
                product={editWIP}
                open={!!editWIP}
                onOpenChange={(open) => !open && setEditWIP(null)}
                onSuccess={onRefetch}
            />

            <StockAllocationDialog
                product={viewAllocation}
                isOpen={!!viewAllocation}
                onClose={() => setViewAllocation(null)}
                saleEvents={saleEvents}
                onUpdate={onRefetch}
            />
            <ProductStatusDialog
                product={editStatusProduct}
                open={!!editStatusProduct}
                onOpenChange={(open) => !open && setEditStatusProduct(null)}
                onSuccess={onRefetch}
            />

            {/* 画像拡大・ダウンロードダイアログ */}
            <Dialog open={!!selectedImage} onOpenChange={(open) => !open && setSelectedImage(null)}>
                <DialogContent className="sm:max-w-[700px] p-0 overflow-hidden bg-black/95 border-none">
                    <DialogTitle className="sr-only">画像プレビュー</DialogTitle>
                    <DialogDescription className="sr-only">商品の拡大画像プレビュー</DialogDescription>
                    {selectedImage && (
                        <div className="relative flex flex-col items-center justify-center min-h-[400px] pt-12 pb-8 px-6">
                            <Button
                                variant="ghost"
                                size="icon"
                                className="absolute top-2 right-2 text-white/70 hover:text-white hover:bg-white/20 rounded-full h-10 w-10 transition-colors"
                                onClick={() => setSelectedImage(null)}
                            >
                                <X className="h-6 w-6" />
                            </Button>

                            <img
                                src={selectedImage.url}
                                alt={selectedImage.alt}
                                className="max-w-full max-h-[75vh] object-contain rounded-md"
                            />

                            <div className="mt-6 flex flex-col items-center gap-4 w-full">
                                <p className="text-white text-base font-medium text-center line-clamp-2 px-12">
                                    {selectedImage.name}
                                </p>
                                <Button
                                    variant="secondary"
                                    className="w-full sm:w-auto flex items-center gap-2 mt-2"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        // ブラウザで直接ダウンロードさせる
                                        fetch(selectedImage.url)
                                            .then(response => response.blob())
                                            .then(blob => {
                                                const url = window.URL.createObjectURL(blob);
                                                const a = document.createElement('a');
                                                a.style.display = 'none';
                                                a.href = url;

                                                // ファイル名生成 (拡張子の推測付き)
                                                const extMatch = selectedImage.url.match(/\.(jpeg|jpg|png|gif|webp)(\?.*)?$/i);
                                                const ext = extMatch ? extMatch[1] : 'jpg';
                                                a.download = `${selectedImage.name}.${ext}`;

                                                document.body.appendChild(a);
                                                a.click();
                                                window.URL.revokeObjectURL(url);
                                                document.body.removeChild(a);
                                            })
                                            .catch(err => {
                                                console.error('Download failed:', err);
                                                // フォールバック（別タブで開く）
                                                window.open(selectedImage.url, '_blank');
                                            });
                                    }}
                                >
                                    <Download className="h-4 w-4" />
                                    画像をダウンロード
                                </Button>
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>
        </Card >
    );
}

"use client";

/**
 * 入荷予定ダイアログ
 * 商品の入荷予定を登録・編集します。
 */

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { CalculableInput } from "@/components/ui/calculable-input";
import { Label } from "@/components/ui/label";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon, Loader2, Trash2 } from "lucide-react";
import { format, addDays } from "date-fns";
import { ja } from "date-fns/locale";
import { cn } from "@/lib/utils";
import type { Product, IncomingStock } from "@/types";
import { useIncomingStock } from "@/hooks/use-incoming-stock";

interface IncomingStockDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    product: Product | null;
    onSuccess?: () => void;
}

export function IncomingStockDialog({ open, onOpenChange, product, onSuccess }: IncomingStockDialogProps) {
    // 状態管理
    const [date, setDate] = useState<Date | undefined>(new Date());
    const [shippedDate, setShippedDate] = useState<Date | undefined>(undefined);
    const [quantity, setQuantity] = useState<string>("");
    const [note, setNote] = useState<string>("");
    const [isSubmitting, setIsSubmitting] = useState(false);

    // 商品ごとの入荷予定データ
    const { incomingStocks, loading: loadingStocks, addIncomingStock, deleteIncomingStock, receiveIncomingStock, refetch } = useIncomingStock(product?.id);

    // ダイアログが開いたときに初期化
    useEffect(() => {
        if (open) {
            setDate(new Date());
            setShippedDate(undefined);
            setQuantity("");
            setNote("");
            refetch();
        }
    }, [open, product, refetch]);

    // 送信ハンドラ
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!product || !date || !quantity) return;

        setIsSubmitting(true);
        try {
            const success = await addIncomingStock({
                productId: product.id,
                expectedDate: format(date, "yyyy-MM-dd"),
                shippedDate: shippedDate ? format(shippedDate, "yyyy-MM-dd") : undefined,
                quantity: parseInt(quantity, 10),
                note: note
            });

            if (success) {
                // フォームをリセット
                setQuantity("");
                setShippedDate(undefined);
                setNote("");
                // 親コンポーネントに通知
                if (onSuccess) onSuccess();
            }
        } catch (error) {
            console.error("入荷予定の登録に失敗しました", error);
        } finally {
            setIsSubmitting(false);
        }
    };

    // 削除ハンドラ
    const handleDelete = async (id: string) => {
        const success = await deleteIncomingStock(id);
        if (success && onSuccess) onSuccess();
    };

    if (!product) return null;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md">
                <DialogHeader>
                    <DialogTitle>入荷予定の管理: {product.name}</DialogTitle>
                </DialogHeader>

                <div className="space-y-6">
                    {/* 新規登録フォーム */}
                    <form onSubmit={handleSubmit} className="space-y-4 border-b pb-6">
                        <Label className="text-base font-semibold">新規登録</Label>

                        <div className="grid gap-2">
                            <Label htmlFor="shippedDate">メーカー出荷予定日</Label>
                            <Popover>
                                <PopoverTrigger asChild>
                                    <Button
                                        variant={"outline"}
                                        className={cn(
                                            "w-full justify-start text-left font-normal",
                                            !shippedDate && "text-muted-foreground"
                                        )}
                                    >
                                        <CalendarIcon className="mr-2 h-4 w-4" />
                                        {shippedDate ? format(shippedDate, "yyyy年MM月dd日", { locale: ja }) : <span>日付を選択</span>}
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-auto p-0">
                                    <Calendar
                                        mode="single"
                                        selected={shippedDate}
                                        onSelect={(newDate) => {
                                            setShippedDate(newDate);
                                            if (newDate) {
                                                // 出荷日の翌日を入荷予定日に設定
                                                setDate(addDays(newDate, 1));
                                            }
                                        }}
                                        initialFocus
                                    />
                                </PopoverContent>
                            </Popover>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="date">入荷（納品）予定日</Label>
                            <Popover>
                                <PopoverTrigger asChild>
                                    <Button
                                        variant={"outline"}
                                        className={cn(
                                            "w-full justify-start text-left font-normal",
                                            !date && "text-muted-foreground"
                                        )}
                                    >
                                        <CalendarIcon className="mr-2 h-4 w-4" />
                                        {date ? format(date, "yyyy年MM月dd日", { locale: ja }) : <span>日付を選択</span>}
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-auto p-0">
                                    <Calendar
                                        mode="single"
                                        selected={date}
                                        onSelect={setDate}
                                        initialFocus
                                    />
                                </PopoverContent>
                            </Popover>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="quantity">数量</Label>
                            <div className="flex items-center gap-2">
                                <CalculableInput
                                    id="quantity"
                                    placeholder="数量を入力"
                                    value={quantity === "0" ? "" : quantity}
                                    onChange={(value) => setQuantity(value === null ? "" : String(value))}
                                    required
                                    stringifyOnComplete
                                />
                                <span className="text-sm text-muted-foreground whitespace-nowrap">
                                    {product.shape?.includes('RZ') || product.shape?.includes('RA') ? 'm' : '枚'}
                                </span>
                            </div>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="note">備考</Label>
                            <Input
                                id="note"
                                placeholder="発注番号など"
                                value={note}
                                onChange={(e) => setNote(e.target.value)}
                            />
                        </div>

                        <Button type="submit" className="w-full" disabled={isSubmitting}>
                            {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            登録する
                        </Button>
                    </form>

                    {/* 登録済みリスト */}
                    <div>
                        <Label className="text-base font-semibold mb-2 block">登録済みの入荷予定</Label>

                        {loadingStocks ? (
                            <div className="text-center py-4 text-muted-foreground">
                                <Loader2 className="h-4 w-4 animate-spin inline mr-2" />
                                読み込み中...
                            </div>
                        ) : incomingStocks.length === 0 ? (
                            <div className="text-center py-4 text-muted-foreground bg-muted/30 rounded-lg">
                                入荷予定はありません
                            </div>
                        ) : (
                            <div className="space-y-2 max-h-[200px] overflow-y-auto pr-1">
                                {incomingStocks.map((stock) => (
                                    <div key={stock.id} className="flex items-center justify-between p-3 border rounded-lg bg-card">
                                        <div>
                                            <div className="text-sm text-muted-foreground">
                                                {stock.shippedDate && `出荷: ${format(new Date(stock.shippedDate), "M/d")} → `}
                                                納品: {format(new Date(stock.expectedDate), "M/d")}
                                            </div>
                                            <div className="text-sm text-muted-foreground">
                                                {stock.quantity.toLocaleString()}
                                                {product.shape?.includes('RZ') || product.shape?.includes('RA') ? 'm' : '枚'}
                                                {stock.note && ` · ${stock.note}`}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={async () => {
                                                    const success = await receiveIncomingStock(stock.id);
                                                    if (success && onSuccess) onSuccess();
                                                }}
                                                className="text-blue-600 hover:text-blue-700 hover:bg-blue-50 border-blue-200 h-8 px-2"
                                                title="在庫に反映します"
                                            >
                                                入荷完了
                                            </Button>
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                onClick={() => handleDelete(stock.id)}
                                                className="text-red-500 hover:text-red-700 hover:bg-red-50 h-8 w-8 p-0"
                                            >
                                                <Trash2 className="h-4 w-4" />
                                            </Button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                <DialogFooter className="mt-4">
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        閉じる
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

