"use client";

import { useState, useEffect, useMemo } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { CalculableInput } from "@/components/ui/calculable-input";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Checkbox } from "@/components/ui/checkbox";
import { FileSpreadsheet, Loader2 } from "lucide-react";
import { Product } from "@/types";
import { useSuppliers } from "@/hooks/use-masters";

import { orderSheetService } from "@/lib/services/order-sheet-service";


// Helper to get recommended quantity
// Real implementation would need history for ALL products.
// For now, we will use a simple rule or fetch history one by one?
// Fetching history for all products at once is heavy.
// Let's use a simpler heuristic for now: max(0, safe_stock - current_stock)
// Or just let user input.

interface OrderSheetDialogProps {
    products: Product[];
    inventoryMap: Map<string, number>;
    trigger?: React.ReactNode;
}

export function OrderSheetDialog({ products, inventoryMap, trigger }: OrderSheetDialogProps) {
    const [open, setOpen] = useState(false);
    const [selectedProducts, setSelectedProducts] = useState<Set<string>>(new Set());
    const [orderQuantities, setOrderQuantities] = useState<Map<string, number>>(new Map());
    const { suppliers } = useSuppliers();

    // Filter low stock items (Simple check: stock < 50 for Roll, < 100 for Sheet)
    // Actually, we can reuse the logic from InventoryPage?
    // Let's duplicate simple logic for now or pass props.

    // Initialize with low stock items when opened
    useEffect(() => {
        if (open) {
            const initialSelection = new Set<string>();
            const initialQuantities = new Map<string, number>();

            products.forEach(p => {
                const stock = inventoryMap.get(p.id) || 0;
                // Simple Low Stock Logic
                const isRoll = p.shape?.includes('巻') || false; // Simple check
                const threshold = isRoll ? 50 : 100;

                if (stock < threshold) {
                    initialSelection.add(p.id);
                    // Default order quantity: 
                    // Roll: 1000 - stock (round up to 500?)
                    // Bag: 3000 - stock (round up to 500?)
                    // Just a placeholder: 
                    const suggested = isRoll ? 1000 : 3000;
                    initialQuantities.set(p.id, suggested);
                }
            });

            // Check if updates are actually needed before calling setState
            if (open) {
                setSelectedProducts(prev => {
                    const areEqual = prev.size === initialSelection.size && [...prev].every(i => initialSelection.has(i));
                    return areEqual ? prev : initialSelection;
                });
                setOrderQuantities(prev => {
                    const areEqual = prev.size === initialQuantities.size && [...prev].every(([k, v]) => initialQuantities.get(k) === v);
                    return areEqual ? prev : initialQuantities;
                });
            }
        }
    }, [open, products, inventoryMap]);

    const handleQuantityChange = (id: string, qty: number) => {
        setOrderQuantities(prev => new Map(prev).set(id, qty));
    };

    const handleToggleSelect = (id: string) => {
        setSelectedProducts(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const handleGenerate = () => {
        // Collect selected items
        const selectedItems = products.filter(p => selectedProducts.has(p.id));
        const quantities = new Map<string, number>();
        selectedItems.forEach(p => {
            quantities.set(p.id, orderQuantities.get(p.id) || 0);
        });

        const supplierMap = new Map(suppliers.map(s => [s.id, s.name]));
        orderSheetService.generateExcel(selectedItems, quantities, supplierMap);
        setOpen(false);
    };

    // Sorted products (Low stock first)
    const sortedProducts = useMemo(() => {
        return [...products].sort((a, b) => {
            const stockA = inventoryMap.get(a.id) || 0;
            const stockB = inventoryMap.get(b.id) || 0;
            return stockA - stockB;
        });
    }, [products, inventoryMap]);

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                {trigger || <Button variant="outline"><FileSpreadsheet className="mr-2 h-4 w-4" />発注書作成</Button>}
            </DialogTrigger>
            <DialogContent className="max-w-4xl max-h-[80vh] flex flex-col">
                <DialogHeader>
                    <DialogTitle>発注書作成</DialogTitle>
                    <DialogDescription>
                        発注が必要な商品を選択し、数量を入力してください。
                    </DialogDescription>
                </DialogHeader>

                <div className="flex-1 overflow-auto border rounded-md">
                    <Table>
                        <TableHeader className="sticky top-0 bg-white z-10">
                            <TableRow>
                                <TableHead className="w-[50px]">選択</TableHead>
                                <TableHead>商品名</TableHead>
                                <TableHead className="text-right">現在庫</TableHead>
                                <TableHead className="w-[120px]">発注数量</TableHead>
                                <TableHead className="w-[80px]">単位</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {sortedProducts.map(product => {
                                const stock = inventoryMap.get(product.id) || 0;
                                const isSelected = selectedProducts.has(product.id);
                                const format = product.category === 'bag' ? '枚' : '個';
                                // Simple safe threshold check for styling
                                const isRoll = product.shape?.includes('巻') || false;
                                const threshold = isRoll ? 50 : 100;
                                const isLow = stock < threshold;

                                return (
                                    <TableRow key={product.id} className={isLow ? "bg-red-50/50" : ""}>
                                        <TableCell>
                                            <Checkbox
                                                checked={isSelected}
                                                onCheckedChange={() => handleToggleSelect(product.id)}
                                            />
                                        </TableCell>
                                        <TableCell>
                                            <div className="font-medium">{product.name}</div>
                                            <div className="text-xs text-muted-foreground">{product.productCode}</div>
                                        </TableCell>
                                        <TableCell className="text-right font-mono">
                                            {stock.toLocaleString()}
                                        </TableCell>
                                        <TableCell>
                                            <CalculableInput
                                                value={orderQuantities.get(product.id) === 0 ? '' : (orderQuantities.get(product.id) || 0)}
                                                onChange={(value) => handleQuantityChange(product.id, typeof value === 'number' ? value : parseInt(value as string) || 0)}
                                                placeholder="数量入力"
                                                className="h-8 text-right"
                                                disabled={!isSelected}
                                            />
                                        </TableCell>
                                        <TableCell>{format}</TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>
                </div>

                <DialogFooter>
                    <div className="flex justify-between w-full items-center">
                        <div className="text-sm text-muted-foreground">
                            {selectedProducts.size} 件選択中
                        </div>
                        <div className="flex gap-2">
                            <Button variant="outline" onClick={() => setOpen(false)}>キャンセル</Button>
                            <Button onClick={handleGenerate} disabled={selectedProducts.size === 0}>
                                <FileSpreadsheet className="mr-2 h-4 w-4" />
                                Excel出力
                            </Button>
                        </div>
                    </div>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import React, { useMemo } from "react";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import {
    LineChart,
    BarChart3,
    TrendingUp,
    TrendingDown,
    Minus,
    Calendar,
    AlertTriangle,
    Info,
    Layers
} from "lucide-react";
import { useStockHistoryAnalysis } from "@/hooks/use-stock-history-analysis";
import { isRollBag, getApproxBagCount } from "@/lib/services";
import { cn } from "@/lib/utils";

import { Product } from "@/types";
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Tooltip,
    Legend
} from 'chart.js';
import { Line } from 'react-chartjs-2';

// Chart.js登録
ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,

    Tooltip,
    Legend
);

// プロップス定義
type ProductAnalysisDialogProps = {
    product: Product;
    currentStock: number;
    trigger?: React.ReactNode;
    open?: boolean;
    onOpenChange?: (open: boolean) => void;
};

export function ProductAnalysisDialog({
    product,
    currentStock,
    trigger,
    open,
    onOpenChange
}: ProductAnalysisDialogProps): React.ReactElement {
    // データフェッチ (Hookを使用)
    const { history, analysis, loading } = useStockHistoryAnalysis(product.id, currentStock);

    // グラフデータ構築ロジック (Corrected for Stock Level)
    const stockLevelChartData = useMemo(() => {
        if (!history || history.length === 0) return null;

        // Sort by date ASC
        const sorted = [...history].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

        // Calculate Stock Level over time (Backwards Replay)
        // Strategy: Start from current stock and subtract/add changes backwards
        let runningStock = currentStock;
        const dataPoints = [];

        // Sort by date DESC for backward replay
        const sortedDesc = [...history].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

        for (const h of sortedDesc) {
            dataPoints.push({
                date: h.date,
                stock: runningStock
            });

            // Reverse the changes
            if (h.type === 'adjustment') {
                // Adjustment means we set it to something. Backwards, we don't know the delta unless stored.
                // Assuming h.changeAmount is the delta (qty_after - qty_before)
                runningStock -= (h.changeAmount || 0);
            } else if (h.type === 'incoming') {
                runningStock -= (h.changeAmount || h.quantity);
            } else if (h.type === 'outgoing' || h.type === 'order') {
                runningStock += (h.changeAmount || h.quantity);
            }
        }

        // Reverse back to chronological for chart
        const chronoData = dataPoints.reverse();
        const recent = chronoData.slice(-30);

        return {
            labels: recent.map(p => {
                const d = new Date(p.date);
                return `${d.getMonth() + 1}/${d.getDate()}`;
            }),
            datasets: [
                {
                    label: '在庫数推移',
                    data: recent.map(p => p.stock),
                    borderColor: 'rgb(59, 130, 246)',
                    backgroundColor: 'rgba(59, 130, 246, 0.5)',
                    tension: 0.3,
                }
            ]
        };
    }, [history]);

    const chartOptions = {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
            legend: {
                display: false,
            },
            title: {
                display: false,
            },
        },
        scales: {
            y: {
                beginAtZero: true,
            },
        },
    };

    if (loading && !analysis) { // Use a better loading check
        return (
            <Dialog open={open} onOpenChange={onOpenChange}>
                {trigger && <DialogTrigger asChild>{trigger}</DialogTrigger>}
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>読み込み中...</DialogTitle>
                    </DialogHeader>
                    <div className="flex justify-center p-8">
                        <div className="animate-spin h-8 w-8 border-4 border-blue-500 rounded-full border-t-transparent"></div>
                    </div>
                </DialogContent>
            </Dialog>
        );
    }

    const isRoll = isRollBag(product.shape || "");
    const unit = isRoll ? "m" : "枚";
    const subUnit = isRoll ? "巻" : null;

    // ロール袋の巻数計算
    const getSubUnitValue = (val: number) => {
        if (!isRoll) return null;
        const rollMeters = product.metersPerRoll || 400;
        return Math.floor(val / rollMeters);
    };

    if (!analysis || !stockLevelChartData) {
        return (
            <Dialog open={open} onOpenChange={onOpenChange}>
                {trigger && <DialogTrigger asChild>{trigger}</DialogTrigger>}
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>{product.name}</DialogTitle>
                    </DialogHeader>
                    <div className="text-center p-8 text-muted-foreground">
                        在庫履歴データがありません。
                    </div>
                </DialogContent>
            </Dialog>
        );
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            {trigger && <DialogTrigger asChild>{trigger}</DialogTrigger>}
            <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <div className="flex items-center gap-2 mb-2">
                        <Badge variant="outline">{product.sku}</Badge>
                        <Badge variant={
                            product.category === 'bag' ? 'default' :
                                product.category === 'sticker' ? 'secondary' : 'outline'
                        }>
                            {product.category === 'bag' ? '米袋' :
                                product.category === 'sticker' ? 'シール' : 'その他'}
                        </Badge>
                    </div>
                    <DialogTitle className="text-xl">{product.name}</DialogTitle>
                    <DialogDescription>
                        {product.weight && `${product.weight}kg`} {product.shape && `/ ${product.shape}`}
                    </DialogDescription>
                </DialogHeader>

                <div className="grid gap-4 py-4">
                    {/* サマリー統計 */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        <Card className="bg-slate-50">
                            <CardHeader className="p-3 pb-1">
                                <CardTitle className="text-xs font-medium text-muted-foreground">週間使用数</CardTitle>
                            </CardHeader>
                            <CardContent className="p-3 pt-1">
                                <div className="text-2xl font-bold">{analysis.weekly.toLocaleString()}</div>
                                {subUnit && (
                                    <div className="text-[10px] text-muted-foreground">
                                        約 {getSubUnitValue(analysis.weekly)} {subUnit}
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                        <Card className="bg-slate-50">
                            <CardHeader className="p-3 pb-1">
                                <CardTitle className="text-xs font-medium text-muted-foreground">月間使用数</CardTitle>
                            </CardHeader>
                            <CardContent className="p-3 pt-1">
                                <div className="text-2xl font-bold">{analysis.monthly.toLocaleString()}</div>
                                {subUnit && (
                                    <div className="text-[10px] text-muted-foreground">
                                        約 {getSubUnitValue(analysis.monthly)} {subUnit}
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                        <Card className="bg-slate-50">
                            <CardHeader className="p-3 pb-1">
                                <CardTitle className="text-xs font-medium text-muted-foreground">3ヶ月使用数</CardTitle>
                            </CardHeader>
                            <CardContent className="p-3 pt-1">
                                <div className="text-2xl font-bold">{analysis.quarterly.toLocaleString()}</div>
                                {subUnit && (
                                    <div className="text-[10px] text-muted-foreground">
                                        約 {getSubUnitValue(analysis.quarterly)} {subUnit}
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                        <Card className="bg-slate-50">
                            <CardHeader className="p-3 pb-1">
                                <CardTitle className="text-xs font-medium text-muted-foreground">1日平均</CardTitle>
                            </CardHeader>
                            <CardContent className="p-3 pt-1">
                                <div className="text-2xl font-bold">{analysis.dailyAverage.toLocaleString()}</div>
                                {subUnit && (
                                    <div className="text-[10px] text-muted-foreground">
                                        約 {((analysis.dailyAverage / (product.metersPerRoll || 400)).toFixed(2))} {subUnit}
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                    </div>

                    {/* 在庫予測＆推奨 */}
                    <div className="grid md:grid-cols-2 gap-4">
                        <Card className={cn(
                            analysis.daysUntilStockout !== null && analysis.daysUntilStockout < 7 ? "border-red-400 bg-red-50" :
                                analysis.daysUntilStockout !== null && analysis.daysUntilStockout < 14 ? "border-amber-400 bg-amber-50" : ""
                        )}>
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-bold flex items-center gap-2">
                                    <Calendar className="h-4 w-4" />
                                    在庫切れ予測
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                {analysis.daysUntilStockout !== null ? (
                                    <div className="space-y-1">
                                        <div className="flex items-end gap-2">
                                            <span className={cn(
                                                "text-3xl font-bold",
                                                analysis.daysUntilStockout < 7 ? "text-red-700" :
                                                    analysis.daysUntilStockout < 14 ? "text-amber-700" : ""
                                            )}>
                                                あと {analysis.daysUntilStockout} 日
                                            </span>
                                        </div>
                                        <p className="text-[11px] text-muted-foreground">
                                            現在のペース（1日 {analysis.dailyAverage}{unit}）で消費した場合
                                        </p>
                                    </div>
                                ) : (
                                    <p className="text-sm text-muted-foreground py-2">データ不足のため算出できません</p>
                                )}
                            </CardContent>
                        </Card>

                        <Card>
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-bold flex items-center gap-2">
                                    <TrendingUp className="h-4 w-4" />
                                    分析とリコメンド
                                </CardTitle>
                            </CardHeader>
                            <CardContent className="space-y-3">
                                <div className="flex items-center gap-3">
                                    <span className="text-xs text-muted-foreground">トレンド:</span>
                                    {analysis.trend === 'increasing' ? (
                                        <Badge className="bg-red-100 text-red-700 hover:bg-red-100 gap-1 pl-1 pr-2 text-[10px]">
                                            <TrendingUp className="h-3 w-3" />
                                            消費増加
                                        </Badge>
                                    ) : analysis.trend === 'decreasing' ? (
                                        <Badge className="bg-green-100 text-green-700 hover:bg-green-100 gap-1 pl-1 pr-2 text-[10px]">
                                            <TrendingDown className="h-3 w-3" />
                                            消費減少
                                        </Badge>
                                    ) : (
                                        <Badge variant="outline" className="gap-1 pl-1 pr-2 text-[10px]">
                                            <Minus className="h-3 w-3" />
                                            安定
                                        </Badge>
                                    )}
                                </div>
                                <div>
                                    <div className="flex items-center gap-1.5 text-xs font-semibold text-slate-700 mb-1">
                                        <Layers className="h-3.5 w-3.5" />
                                        推奨発注数
                                    </div>
                                    <div className="flex items-baseline gap-1">
                                        <span className="text-xl font-bold text-primary">{analysis.suggestedOrderQuantity.toLocaleString()}</span>
                                        <span className="text-[10px] text-muted-foreground">{unit}</span>
                                        {subUnit && (
                                            <span className="text-xs text-slate-500 ml-2">
                                                (約 {getSubUnitValue(analysis.suggestedOrderQuantity)} {subUnit})
                                            </span>
                                        )}
                                    </div>
                                    <p className="text-[10px] text-muted-foreground mt-1">
                                        ※月間使用数の1.2倍を基準に算出
                                    </p>
                                </div>
                            </CardContent>
                        </Card>
                    </div>

                    {/* グラフ */}
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">在庫推移（直近30回分）</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="h-[200px] w-full">
                                {stockLevelChartData && <Line data={stockLevelChartData} options={chartOptions} />}
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </DialogContent>
        </Dialog>
    );
}

