"use client";

import { useState, useEffect } from "react";
import { Product, SupplierStockLot, DeliveryAddress } from "@/types";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { CalculableInput } from "@/components/ui/calculable-input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
// import { format } from "date-fns"; // Unused
import { useWIPActions } from "@/hooks/use-work-in-progress";
import { Package, ArrowRight, Loader2, Plus, Trash2, Save, X, Edit2 } from "lucide-react";
import toast from "react-hot-toast";

interface SupplierStockDialogProps {
    product: Product | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    currentStock: number;
    onSuccess: () => void;
}

export function SupplierStockDialog({
    product,
    open,
    onOpenChange,
    currentStock, // この値も参考にしますが、最新のロット合算値を使用します
    onSuccess,
}: SupplierStockDialogProps) {
    const [lots, setLots] = useState<SupplierStockLot[]>([]);
    const [isLoadingLots, setIsLoadingLots] = useState(false);

    // 新規ロット追加フォーム
    const [newLotQuantity, setNewLotQuantity] = useState<number>(0);
    const [newLotDate, setNewLotDate] = useState<string>(new Date().toISOString().split('T')[0]);
    const [newLotNote, setNewLotNote] = useState<string>('');
    const [isAddingLot, setIsAddingLot] = useState(false);

    // 編集用ステート
    const [editingLotId, setEditingLotId] = useState<string | null>(null);
    const [editLotQuantity, setEditLotQuantity] = useState<number>(0);
    const [editLotDate, setEditLotDate] = useState<string>('');
    const [editLotNote, setEditLotNote] = useState<string>('');

    // 入荷予定の複数スケジュール管理
    type ArrivalSchedule = {
        id: string;
        expectedDate: string;
        quantity: number;
        note: string;
    };
    const [arrivalSchedules, setArrivalSchedules] = useState<ArrivalSchedule[]>([]);

    // 納品先リスト
    const [deliveryAddresses, setDeliveryAddresses] = useState<DeliveryAddress[]>([]);

    const fetchDeliveryAddresses = async () => {
        try {
            const res = await fetch('/api/delivery-addresses');
            const result = await res.json();
            if (Array.isArray(result)) {
                setDeliveryAddresses(result);
            } else if (result && result.data && Array.isArray(result.data)) {
                setDeliveryAddresses(result.data);
            }
        } catch (e) {
            console.error("納品先取得エラー", e);
        }
    };

    useEffect(() => {
        let isMounted = true;
        if (open) {
            fetchDeliveryAddresses().then(() => {
                // If we need to do something after fetch
            });
        }
        return () => { isMounted = false; };
    }, [open]);

    const {
        getSupplierStockLots,
        addSupplierStockLot,
        updateSupplierStockLot,
        deleteSupplierStockLot,
        moveSupplierStockToIncoming,
        syncSupplierStock,
        loading
    } = useWIPActions();

    const handleSync = async () => {
        if (!confirm("すべての商品のメーカー在庫を、ロットの合計値に合わせる再計算（同期）を行ってもよろしいですか？")) return;

        const success = await syncSupplierStock();
        if (success) {
            toast.success("在庫数を再計算しました");
            fetchLots();
            onSuccess();
        } else {
            toast.error("再計算に失敗しました");
        }
    };

    const fetchLots = async () => {
        if (!product) return;
        setIsLoadingLots(true);
        const data = await getSupplierStockLots(product.id);
        setLots(data);
        setIsLoadingLots(false);
    };

    // ダイアログが開くたびに初期値をセット
    useEffect(() => {
        if (open && product) {
            setArrivalSchedules([
                { id: crypto.randomUUID(), expectedDate: new Date().toISOString().split('T')[0], quantity: 0, note: '' }
            ]);

            // フォームのリセット
            setNewLotQuantity(0);
            setNewLotDate(new Date().toISOString().split('T')[0]);
            setNewLotNote('');
            setIsAddingLot(false);
            setEditingLotId(null);

            fetchLots();
        }
    }, [open, product]);

    const totalStock = lots.reduce((sum, lot) => sum + lot.quantity, 0);
    const displayStock = lots.length > 0 ? totalStock : currentStock;

    const handleAddLot = async () => {
        if (!product || newLotQuantity <= 0 || !newLotDate) return;

        const success = await addSupplierStockLot(product.id, newLotQuantity, newLotDate, newLotNote);
        if (success) {
            toast.success("ロットを追加しました");
            setNewLotQuantity(0);
            setNewLotNote('');
            setIsAddingLot(false);
            fetchLots();
            onSuccess();
        } else {
            toast.error("ロットの追加に失敗しました");
        }
    };

    const handleStartEdit = (lot: SupplierStockLot) => {
        setEditingLotId(lot.id);
        setEditLotQuantity(lot.quantity);
        setEditLotDate(lot.stockDate);
        setEditLotNote(lot.note || '');
    };

    const handleSaveEdit = async () => {
        if (!editingLotId || editLotQuantity < 0 || !editLotDate) return;

        const success = await updateSupplierStockLot(editingLotId, editLotQuantity, editLotDate, editLotNote);
        if (success) {
            toast.success("ロットを更新しました");
            setEditingLotId(null);
            fetchLots();
            onSuccess();
        } else {
            toast.error("ロットの更新に失敗しました");
        }
    };

    const handleDeleteLot = async (lotId: string) => {
        if (!confirm("このロットを削除してもよろしいですか？")) return;

        const success = await deleteSupplierStockLot(lotId);
        if (success) {
            toast.success("ロットを削除しました");
            fetchLots();
            onSuccess();
        } else {
            toast.error("ロットの削除に失敗しました");
        }
    };

    const addArrivalRow = () => {
        setArrivalSchedules([
            ...arrivalSchedules,
            { id: crypto.randomUUID(), expectedDate: new Date().toISOString().split('T')[0], quantity: 0, note: '' }
        ]);
    };

    const removeArrivalRow = (id: string) => {
        if (arrivalSchedules.length <= 1) return;
        setArrivalSchedules(arrivalSchedules.filter(s => s.id !== id));
    };

    const updateArrivalRow = (id: string, updates: Partial<ArrivalSchedule>) => {
        setArrivalSchedules(arrivalSchedules.map(s => s.id === id ? { ...s, ...updates } : s));
    };

    const handleMove = async () => {
        const activeSchedules = arrivalSchedules.filter(s => s.quantity > 0);
        if (!product || activeSchedules.length === 0) return;

        const totalMoveQuantity = activeSchedules.reduce((sum, s) => sum + s.quantity, 0);

        if (totalMoveQuantity > displayStock) {
            toast.error("メーカー在庫以上の数量は移動できません");
            return;
        }

        const success = await moveSupplierStockToIncoming(product.id, activeSchedules.map(s => ({
            expectedDate: s.expectedDate,
            quantity: s.quantity,
            note: s.note
        })));

        if (success) {
            toast.success("入荷予定へ移動しました");
            onSuccess();
            onOpenChange(false);
        } else {
            toast.error("移動に失敗しました");
        }
    };

    if (!product) return null;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>メーカー在庫（ロット管理）</DialogTitle>
                    <DialogDescription>
                        {product.name} のメーカー在庫管理を行います。
                    </DialogDescription>
                </DialogHeader>

                <div className="grid gap-6 py-4">
                    {/* 合算値表示 */}
                    <div className="bg-blue-50/50 p-4 rounded-lg flex items-center justify-between border border-blue-100">
                        <div className="flex items-center gap-3">
                            <Package className="h-8 w-8 text-blue-500" />
                            <div>
                                <p className="text-sm font-medium text-blue-600">現在のメーカー在庫合算</p>
                                <p className="text-3xl font-bold">{displayStock.toLocaleString()}</p>
                            </div>
                        </div>
                        <Button
                            variant="outline"
                            size="sm"
                            className="text-xs h-8 border-blue-200 text-blue-600 hover:bg-blue-50"
                            onClick={handleSync}
                            disabled={loading}
                        >
                            {loading ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <Save className="h-3 w-3 mr-1" />}
                            再計算
                        </Button>
                    </div>

                    <Separator />

                    {/* ロット一覧と追加 */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h4 className="text-sm font-medium leading-none">ロット一覧</h4>
                            {!isAddingLot && (
                                <Button size="sm" variant="outline" onClick={() => setIsAddingLot(true)}>
                                    <Plus className="h-4 w-4 mr-1" />
                                    新規追加
                                </Button>
                            )}
                        </div>

                        {/* 新規追加フォーム */}
                        {isAddingLot && (
                            <div className="bg-muted/50 p-4 rounded-md border space-y-3 relative">
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="absolute top-2 right-2 h-6 w-6"
                                    onClick={() => setIsAddingLot(false)}
                                >
                                    <X className="h-4 w-4" />
                                </Button>
                                <h5 className="text-xs font-semibold text-muted-foreground uppercase">新しいロットの追加</h5>
                                <div className="grid grid-cols-2 gap-3">
                                    <div className="space-y-1">
                                        <Label className="text-xs">入庫/製造日</Label>
                                        <Input type="date" size={1} className="h-8" value={newLotDate} onChange={e => setNewLotDate(e.target.value)} />
                                    </div>
                                    <div className="space-y-1">
                                        <Label className="text-xs">数量</Label>
                                        <CalculableInput className="h-8" value={newLotQuantity === 0 ? "" : newLotQuantity} onChange={value => setNewLotQuantity(Number(value) || 0)} placeholder="数量" />
                                    </div>
                                    <div className="col-span-2 space-y-1">
                                        <Label className="text-xs">メモ (任意)</Label>
                                        <Input className="h-8" placeholder="ロット番号や備考..." value={newLotNote} onChange={e => setNewLotNote(e.target.value)} />
                                    </div>
                                </div>
                                <Button className="w-full h-8 flex items-center justify-center" disabled={loading || newLotQuantity <= 0} onClick={handleAddLot}>
                                    {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Save className="h-4 w-4 mr-2" />}
                                    追加する
                                </Button>
                            </div>
                        )}

                        {/* ロットリスト */}
                        <div className="border rounded-md divide-y">
                            {isLoadingLots ? (
                                <div className="p-8 text-center text-muted-foreground flex items-center justify-center">
                                    <Loader2 className="h-6 w-6 animate-spin mr-2" />
                                    読み込み中...
                                </div>
                            ) : lots.length === 0 ? (
                                <div className="p-8 text-center text-muted-foreground text-sm">
                                    登録されているロットはありません。
                                </div>
                            ) : (
                                lots.map(lot => (
                                    <div key={lot.id} className="p-3 bg-white flex flex-col gap-2">
                                        {editingLotId === lot.id ? (
                                            <div className="grid grid-cols-2 gap-2">
                                                <Input type="date" value={editLotDate} onChange={e => setEditLotDate(e.target.value)} className="h-8 text-sm" />
                                                <CalculableInput value={editLotQuantity === 0 ? "" : editLotQuantity} onChange={value => setEditLotQuantity(Number(value) || 0)} className="h-8 text-sm" placeholder="数量" />
                                                <Input value={editLotNote} onChange={e => setEditLotNote(e.target.value)} placeholder="メモ" className="col-span-2 h-8 text-sm" />
                                                <div className="col-span-2 flex justify-end gap-2 mt-1">
                                                    <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setEditingLotId(null)}>キャンセル</Button>
                                                    <Button size="sm" className="h-7 text-xs" onClick={handleSaveEdit} disabled={loading}>保存</Button>
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="flex items-center justify-between">
                                                <div>
                                                    <div className="flex items-center gap-2">
                                                        <span className="font-semibold text-lg">{lot.quantity.toLocaleString()}</span>
                                                        <span className="text-xs text-muted-foreground bg-muted px-2 py-0.5 rounded border">{lot.stockDate}</span>
                                                    </div>
                                                    {lot.note && <div className="text-xs text-gray-500 mt-0.5">{lot.note}</div>}
                                                </div>
                                                <div className="flex items-center gap-1 opacity-50 hover:opacity-100 transition-opacity">
                                                    <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => handleStartEdit(lot)}>
                                                        <Edit2 className="h-4 w-4 text-blue-600" />
                                                    </Button>
                                                    <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => handleDeleteLot(lot.id)}>
                                                        <Trash2 className="h-4 w-4 text-red-600" />
                                                    </Button>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </div>

                    <Separator />

                    {/* 在庫移動セクション */}
                    <div className="space-y-4 bg-orange-50/50 p-4 rounded-lg border border-orange-100">
                        <h4 className="text-sm font-medium leading-none text-orange-800 flex items-center">
                            <ArrowRight className="h-4 w-4 mr-1.5" />
                            入荷予定へ移動（出荷指示）
                        </h4>
                        <p className="text-[11px] text-orange-700/80 leading-relaxed">
                            メーカー在庫の合算値から指定数量を出荷させ、自社の入荷予定に移動します。<br />
                            内部的には、最も古い日付のロットから順に自動で消費されます（FIFO方式）。
                        </p>
                        <div className="flex items-center justify-between mb-4 mt-2">
                            <div className="flex items-center gap-2">
                                <span className="text-sm font-semibold text-orange-900 border-b-2 border-orange-500 pb-0.5">入荷予定</span>
                                <span className="text-xs text-orange-700">に移動する数量（複数回答可）</span>
                            </div>
                            <Button variant="outline" size="sm" className="h-7 text-xs bg-white hover:bg-orange-50 text-orange-700 border-orange-200" onClick={addArrivalRow}>
                                <Plus className="h-3 w-3 mr-1" />
                                予定追加
                            </Button>
                        </div>

                        <div className="space-y-3">
                            {arrivalSchedules.map((schedule) => (
                                <div key={schedule.id} className="relative bg-white p-3 rounded-md border border-orange-200 shadow-sm space-y-3">
                                    {arrivalSchedules.length > 1 && (
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            className="absolute top-1 right-1 h-6 w-6 text-muted-foreground hover:text-red-500 hover:bg-red-50"
                                            onClick={() => removeArrivalRow(schedule.id)}
                                        >
                                            <X className="h-3 w-3" />
                                        </Button>
                                    )}

                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="space-y-1">
                                            <Label className="text-xs text-orange-800">着日（入荷予定日）</Label>
                                            <Input
                                                type="date"
                                                value={schedule.expectedDate}
                                                onChange={(e) => updateArrivalRow(schedule.id, { expectedDate: e.target.value })}
                                                size={1}
                                                className="h-8 border-orange-100 focus-visible:ring-orange-500 input-placeholder-orange focus:border-orange-500"
                                            />
                                        </div>
                                        <div className="space-y-1">
                                            <Label className="text-xs text-orange-800">移動数量</Label>
                                            <CalculableInput
                                                value={schedule.quantity === 0 ? "" : schedule.quantity}
                                                onChange={(value) => updateArrivalRow(schedule.id, { quantity: Number(value) || 0 })}
                                                placeholder="数量"
                                                className="h-8 border-orange-100 focus-visible:ring-orange-500 input-placeholder-orange focus:border-orange-500"
                                            />
                                        </div>
                                    </div>

                                    <div className="space-y-1">
                                        <Label className="text-xs text-orange-800">出荷先（納品先マスターから選択）</Label>
                                        <Select
                                            value={schedule.note}
                                            onValueChange={(val) => updateArrivalRow(schedule.id, { note: val })}
                                        >
                                            <SelectTrigger className="h-8 border-orange-100 bg-white focus:ring-orange-500">
                                                <SelectValue placeholder="出荷先を選択（任意）" />
                                            </SelectTrigger>
                                            <SelectContent>
                                                {deliveryAddresses.map(addr => (
                                                    <SelectItem key={addr.id} value={addr.name}>
                                                        {addr.name}
                                                    </SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="flex justify-between items-center mt-4 pt-4 border-t border-orange-200">
                            <div className="text-sm">
                                <span className="text-orange-900">移動合計: </span>
                                <span className="font-bold text-orange-700 text-lg">{arrivalSchedules.reduce((sum, s) => sum + s.quantity, 0).toLocaleString()}</span>
                            </div>
                            <Button
                                variant="default"
                                onClick={handleMove}
                                disabled={loading || arrivalSchedules.reduce((sum, s) => sum + s.quantity, 0) <= 0 || arrivalSchedules.reduce((sum, s) => sum + s.quantity, 0) > displayStock}
                                className="whitespace-nowrap bg-orange-500 hover:bg-orange-600 text-white shadow-sm"
                            >
                                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                移動実行
                            </Button>
                        </div>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Product } from "@/types";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { CalculableInput } from "@/components/ui/calculable-input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { useWIPActions, useWorkInProgress } from "@/hooks/use-work-in-progress";
import { format, endOfMonth, setDate } from "date-fns";
import { Plus, Check, Loader2, Trash2, CalendarClock, PackageCheck } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "react-hot-toast";
import type { WorkInProgress, DeliveryAddress } from "@/types";
import { X } from "lucide-react";

interface WIPDialogProps {
    product: Product | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSuccess: () => void;
}

export function WIPDialog({
    product,
    open,
    onOpenChange,
    onSuccess,
}: WIPDialogProps) {
    const [activeTab, setActiveTab] = useState("list");

    // itemsの取得 (in_progress)
    const { items: inProgressItems, loading: loadingInProgress, refetch: refetchInProgress } = useWorkInProgress({
        productId: product?.id,
        status: 'in_progress'
    });

    // itemsの取得 (completed)
    const { items: completedItems, loading: loadingCompleted, refetch: refetchCompleted } = useWorkInProgress({
        productId: product?.id,
        status: 'completed'
    });

    // refetchをuseCallbackで安定化して無限ループを防止
    const refetch = useCallback(() => {
        refetchInProgress();
        refetchCompleted();
    }, [refetchInProgress, refetchCompleted]);

    useEffect(() => {
        if (activeTab === 'history') {
            refetchCompleted();
        }
    }, [activeTab, refetchCompleted]);

    // アクション
    const { createWIP, updateWIP, arrangeShipping, transferToIncoming, transferToSupplier, deleteWIP, loading: actionLoading } = useWIPActions();

    // フォーム状態
    const [editingWIPId, setEditingWIPId] = useState<string | null>(null);
    const [quantity, setQuantity] = useState(0);
    const [startedAt, setStartedAt] = useState(format(new Date(), 'yyyy-MM-dd'));
    const [dateType, setDateType] = useState<'specific' | 'vague'>('specific');
    const [specificDate, setSpecificDate] = useState("");

    // 旬管理用ステート
    const [vagueMonth, setVagueMonth] = useState(format(new Date(), 'yyyy-MM'));
    const [vagueTerm, setVagueTerm] = useState<'early' | 'mid' | 'late'>('early');

    const [note, setNote] = useState("");

    // 確定処理用ステート（分割移動対応）
    const [confirmingId, setConfirmingId] = useState<string | null>(null);
    const [confirmingItem, setConfirmingItem] = useState<WorkInProgress | null>(null);
    const [supplierQuantity, setSupplierQuantity] = useState(0); // メーカー在庫への数量

    // 入荷予定の複数スケジュール管理
    type ArrivalSchedule = {
        id: string;
        expectedDate: string;
        quantity: number;
        note: string;
    };
    const [arrivalSchedules, setArrivalSchedules] = useState<ArrivalSchedule[]>([]);

    const [lossQuantity, setLossQuantity] = useState(0); // ロス数量

    // 納品先リスト
    const [deliveryAddresses, setDeliveryAddresses] = useState<DeliveryAddress[]>([]);

    const fetchDeliveryAddresses = async () => {
        try {
            const res = await fetch('/api/delivery-addresses');
            const result = await res.json();
            if (Array.isArray(result)) {
                setDeliveryAddresses(result);
            } else if (result && result.data && Array.isArray(result.data)) {
                setDeliveryAddresses(result.data);
            }
        } catch (e) {
            console.error("納品先取得エラー", e);
        }
    };

    useEffect(() => {
        let isMounted = true;
        if (open) {
            fetchDeliveryAddresses();
        }
        return () => { isMounted = false; };
    }, [open]);

    // ダイアログが開いたときに再取得（refetchを依存配列から除外して無限ループ防止）
    useEffect(() => {
        if (open && product) {
            refetchInProgress();
            setArrivalSchedules([]);
            setConfirmingId(null);
            setConfirmingItem(null);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open, product?.id]);

    const resetForm = () => {
        setEditingWIPId(null);
        setQuantity(0);
        setNote("");
        setStartedAt(format(new Date(), 'yyyy-MM-dd'));
        setDateType('specific');
        setSpecificDate("");
    };

    const handleEditClick = (item: WorkInProgress) => {
        setEditingWIPId(item.id);
        setQuantity(item.quantity);
        setStartedAt(format(new Date(item.startedAt), 'yyyy-MM-dd'));
        setNote(item.note || "");
        if (item.termType === 'specific' || !item.termType) {
            setDateType('specific');
            setSpecificDate(item.expectedCompletion ? format(new Date(item.expectedCompletion), 'yyyy-MM-dd') : "");
        } else {
            setDateType('vague');
            setVagueTerm(item.termType as 'early' | 'mid' | 'late');
            if (item.expectedCompletion) {
                setVagueMonth(format(new Date(item.expectedCompletion), 'yyyy-MM'));
            }
        }
        setActiveTab("add");
    };

    const handleCreateOrUpdate = async () => {
        if (!product) return;
        if (quantity <= 0) return;

        let expectedCompletion: string | undefined = undefined;
        let termType: 'specific' | 'early' | 'mid' | 'late' = 'specific';

        if (dateType === 'specific') {
            expectedCompletion = specificDate || undefined;
        } else {
            termType = vagueTerm;
            // ソート用に仮の日付を設定
            const [year, month] = vagueMonth.split('-').map(Number);
            const baseDate = new Date(year, month - 1, 1);

            if (vagueTerm === 'early') {
                expectedCompletion = format(setDate(baseDate, 10), 'yyyy-MM-dd');
            } else if (vagueTerm === 'mid') {
                expectedCompletion = format(setDate(baseDate, 20), 'yyyy-MM-dd');
            } else {
                expectedCompletion = format(endOfMonth(baseDate), 'yyyy-MM-dd');
            }
        }

        let result;
        if (editingWIPId) {
            const success = await updateWIP(editingWIPId, {
                quantity,
                started_at: startedAt,
                expected_completion: expectedCompletion,
                term_type: termType,
                note: note || undefined,
            } as any);
            result = { success };
        } else {
            result = await createWIP({
                productId: product.id,
                quantity,
                startedAt,
                expectedCompletion,
                termType,
                note: note || undefined,
            });
        }

        if (result.success) {
            onSuccess();
            refetch();
            setActiveTab("list");
            resetForm();
        }
    };

    const handleArrangeShipping = async (id: string) => {
        if (!confirm("手配した数量を出荷済みにし、仕掛中から完了させます。よろしいですか？")) return;
        const success = await arrangeShipping(id);
        if (success) {
            toast.success("出荷手配を完了しました");
            onSuccess();
            refetch();
        } else {
            toast.error("処理に失敗しました");
        }
    };

    // 仕上がり移動開始
    const handleStartTransfer = (item: WorkInProgress) => {
        setConfirmingId(item.id);
        setConfirmingItem(item);
        setSupplierQuantity(0);
        setArrivalSchedules([
            { id: crypto.randomUUID(), expectedDate: format(new Date(), 'yyyy-MM-dd'), quantity: 0, note: '' }
        ]);
        setLossQuantity(0);
    };

    const addArrivalRow = () => {
        setArrivalSchedules([
            ...arrivalSchedules,
            { id: crypto.randomUUID(), expectedDate: format(new Date(), 'yyyy-MM-dd'), quantity: 0, note: '' }
        ]);
    };

    const removeArrivalRow = (id: string) => {
        if (arrivalSchedules.length <= 1) return;
        setArrivalSchedules(arrivalSchedules.filter(s => s.id !== id));
    };

    const updateArrivalRow = (id: string, updates: Partial<ArrivalSchedule>) => {
        setArrivalSchedules(arrivalSchedules.map(s => s.id === id ? { ...s, ...updates } : s));
    };

    // 分割移動の合計数量（ロス含む）
    const incomingTotal = arrivalSchedules.reduce((sum, s) => sum + s.quantity, 0);
    const totalTransferQuantity = supplierQuantity + incomingTotal;
    const totalConsumedQuantity = totalTransferQuantity + lossQuantity;
    const remainingQuantity = confirmingItem ? confirmingItem.quantity - totalConsumedQuantity : 0;
    const isTransferValid = totalConsumedQuantity > 0 && totalConsumedQuantity <= (confirmingItem?.quantity || 0);

    const handleSubmitConfirm = async () => {
        if (!confirmingId || !confirmingItem) return;
        if (!isTransferValid) return;

        let success = true;

        // メーカー在庫への移動
        if (supplierQuantity > 0) {
            const result = await transferToSupplier(confirmingId, supplierQuantity);
            if (!result) success = false;
        }

        // 入荷予定への移動
        const activeSchedules = arrivalSchedules.filter(s => s.quantity > 0);
        if (activeSchedules.length > 0 && success) {
            const result = await transferToIncoming(confirmingId, activeSchedules.map(s => ({
                expectedDate: s.expectedDate,
                quantity: s.quantity,
                note: s.note
            })));
            if (!result) success = false;
        }

        if (success) {
            // 全量消化の場合はWIPを削除
            if (remainingQuantity <= 0) {
                await deleteWIP(confirmingId);
                const parts = [];
                if (totalTransferQuantity > 0) parts.push(`${totalTransferQuantity.toLocaleString()}を移動`);
                if (lossQuantity > 0) parts.push(`ロス ${lossQuantity.toLocaleString()}`);
                toast.success(parts.join('、'));
            } else {
                // 残数がある場合はWIPの数量を残数に更新
                await updateWIP(confirmingId, { quantity: remainingQuantity });
                const parts = [];
                if (totalTransferQuantity > 0) parts.push(`${totalTransferQuantity.toLocaleString()}を移動`);
                if (lossQuantity > 0) parts.push(`ロス ${lossQuantity.toLocaleString()}`);
                parts.push(`${remainingQuantity.toLocaleString()}を仕掛中に残しました`);
                toast.success(parts.join('、'));
            }
            onSuccess();
            refetch();
            setConfirmingId(null);
            setConfirmingItem(null);
        } else {
            toast.error('移動処理に失敗しました');
        }
    };



    const handleDelete = async (id: string) => {
        if (!confirm("本当に削除しますか？")) return;
        const success = await deleteWIP(id);
        if (success) {
            onSuccess();
            refetch();
        }
    };

    // 日付表示フォーマッター
    const displayDate = (dateStr: string | null, termType: string) => {
        if (!dateStr) return "未定";
        if (termType === 'specific' || !termType) return format(new Date(dateStr), 'yyyy/MM/dd');

        const date = new Date(dateStr);
        const month = format(date, 'M月');

        switch (termType) {
            case 'early': return `${month}上旬`;
            case 'mid': return `${month}中旬`;
            case 'late': return `${month}下旬`;
            default: return format(date, 'yyyy/MM/dd');
        }
    };

    if (!product) return null;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[600px]">
                <DialogHeader>
                    <DialogTitle>仕掛中（加工中）管理</DialogTitle>
                    <DialogDescription>
                        {product.name} の仕掛品・仕掛状況管理
                    </DialogDescription>
                </DialogHeader>

                {confirmingId && confirmingItem ? (
                    // 仕上がり移動画面（分割対応）
                    <div className="space-y-4 py-2">
                        <div className="bg-blue-50 p-3 rounded-md border border-blue-200 text-sm mb-4">
                            仕掛中の商品（{confirmingItem.quantity.toLocaleString()}）を移動先に振り分けてください。
                            一部のみ移動し、残りを仕掛中に残すことも可能です。
                        </div>

                        <div className="grid gap-4">
                            {/* メーカー在庫への移動 */}
                            <div className="border rounded-lg p-4 space-y-3">
                                <div className="flex items-center gap-2">
                                    <Badge variant="outline" className="text-orange-600 border-orange-200 bg-orange-50">メーカー在庫</Badge>
                                    <span className="text-sm text-muted-foreground">に移動する数量</span>
                                </div>
                                <CalculableInput
                                    value={supplierQuantity === 0 ? "" : supplierQuantity}
                                    onChange={(value) => setSupplierQuantity(Number(value) || 0)}
                                    placeholder="0 (移動しない場合は空欄)"
                                />
                            </div>

                            {/* 入荷予定への移動 */}
                            <div className="border rounded-lg p-4 space-y-4">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <Badge variant="outline" className="text-emerald-600 border-emerald-200 bg-emerald-50">入荷予定</Badge>
                                        <span className="text-sm text-muted-foreground">に移動する数量（複数回答可）</span>
                                    </div>
                                    <Button variant="outline" size="sm" className="h-7 text-xs" onClick={addArrivalRow}>
                                        <Plus className="h-3 w-3 mr-1" />
                                        予定追加
                                    </Button>
                                </div>

                                <div className="space-y-4 pt-2">
                                    {arrivalSchedules.map((schedule, index) => (
                                        <div key={schedule.id} className="relative bg-muted/20 p-3 rounded-md border space-y-3">
                                            {arrivalSchedules.length > 1 && (
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="absolute top-1 right-1 h-6 w-6 text-muted-foreground hover:text-red-500"
                                                    onClick={() => removeArrivalRow(schedule.id)}
                                                >
                                                    <X className="h-4 w-4" />
                                                </Button>
                                            )}

                                            <div className="grid grid-cols-2 gap-3">
                                                <div className="space-y-1">
                                                    <Label className="text-xs">着日（入荷予定日）</Label>
                                                    <Input
                                                        type="date"
                                                        value={schedule.expectedDate}
                                                        onChange={(e) => updateArrivalRow(schedule.id, { expectedDate: e.target.value })}
                                                        size={1}
                                                        className="h-8"
                                                    />
                                                </div>
                                                <div className="space-y-1">
                                                    <Label className="text-xs">数量</Label>
                                                    <CalculableInput
                                                        value={schedule.quantity === 0 ? "" : schedule.quantity}
                                                        onChange={(value) => updateArrivalRow(schedule.id, { quantity: Number(value) || 0 })}
                                                        placeholder="数量"
                                                        className="h-8"
                                                    />
                                                </div>
                                            </div>

                                            <div className="space-y-1">
                                                <Label className="text-xs">出荷先（納品先マスターから選択）</Label>
                                                <Select
                                                    value={schedule.note}
                                                    onValueChange={(val) => updateArrivalRow(schedule.id, { note: val })}
                                                >
                                                    <SelectTrigger className="h-8">
                                                        <SelectValue placeholder="出荷先を選択（任意）" />
                                                    </SelectTrigger>
                                                    <SelectContent>
                                                        {deliveryAddresses.map(addr => (
                                                            <SelectItem key={addr.id} value={addr.name}>
                                                                {addr.name}
                                                            </SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* ロス */}
                            <div className="border rounded-lg p-4 space-y-3 border-dashed border-red-200">
                                <div className="flex items-center gap-2">
                                    <Badge variant="outline" className="text-red-600 border-red-200 bg-red-50">ロス</Badge>
                                    <span className="text-sm text-muted-foreground">加工ロス・廃棄分</span>
                                </div>
                                <CalculableInput
                                    value={lossQuantity === 0 ? "" : lossQuantity}
                                    onChange={(value) => setLossQuantity(Number(value) || 0)}
                                    placeholder="0 (ロスなしの場合は空欄)"
                                />
                            </div>

                            {/* 残数サマリー */}
                            <div className={`p-3 rounded-md text-sm ${totalConsumedQuantity > (confirmingItem?.quantity || 0) ? 'bg-red-50 border border-red-200 text-red-700' : remainingQuantity > 0 ? 'bg-amber-50 border border-amber-200 text-amber-700' : 'bg-green-50 border border-green-200 text-green-700'}`}>
                                <div className="flex justify-between items-center">
                                    <span>仕掛中の数量:</span>
                                    <span className="font-medium">{confirmingItem.quantity.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span>移動合計:</span>
                                    <span className="font-medium">{totalTransferQuantity.toLocaleString()}</span>
                                </div>
                                {lossQuantity > 0 && (
                                    <div className="flex justify-between items-center text-red-600">
                                        <span>ロス:</span>
                                        <span className="font-medium">-{lossQuantity.toLocaleString()}</span>
                                    </div>
                                )}
                                <hr className="my-1 border-current opacity-30" />
                                <div className="flex justify-between items-center font-bold">
                                    <span>{remainingQuantity > 0 ? '仕掛中に残る数量:' : '状態:'}</span>
                                    <span>{remainingQuantity > 0 ? remainingQuantity.toLocaleString() : totalConsumedQuantity > (confirmingItem?.quantity || 0) ? '超過しています' : '全量消化'}</span>
                                </div>
                            </div>
                        </div>

                        <DialogFooter className="mt-6">
                            <Button variant="outline" onClick={() => {
                                setConfirmingId(null);
                                setConfirmingItem(null);
                            }}>キャンセル</Button>
                            <Button onClick={handleSubmitConfirm} disabled={actionLoading || !isTransferValid}>
                                {actionLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                確定して移動
                            </Button>
                        </DialogFooter>
                    </div>
                ) : (
                    <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                        <TabsList className="grid w-full grid-cols-3">
                            <TabsTrigger value="list" onClick={resetForm}>一覧 ({inProgressItems.length})</TabsTrigger>
                            <TabsTrigger value="add" onClick={resetForm}>{editingWIPId ? '編集' : '新規登録'}</TabsTrigger>
                            <TabsTrigger value="history" onClick={resetForm}>履歴 ({completedItems.length})</TabsTrigger>
                        </TabsList>

                        <TabsContent value="list" className="mt-4 space-y-4">
                            {loadingInProgress ? (
                                <div className="flex justify-center py-8">
                                    <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                                </div>
                            ) : inProgressItems.length === 0 ? (
                                <div className="text-center py-8 text-muted-foreground">
                                    仕掛中のアイテムはありません。
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {inProgressItems.map((item) => (
                                        <div key={item.id} className="flex flex-col p-4 border rounded-lg gap-3">
                                            <div className="flex items-center justify-between">
                                                <div className="font-medium flex items-center gap-2">
                                                    <span className="text-lg">{item.quantity.toLocaleString()}</span>
                                                    {item.confirmationStatus === 'confirmed' ? (
                                                        <Badge variant="outline" className="text-blue-600 border-blue-200 bg-blue-50">
                                                            仕掛確定済
                                                        </Badge>
                                                    ) : item.confirmationStatus === 'scheduled' ? (
                                                        <Badge variant="outline" className="text-emerald-600 border-emerald-200 bg-emerald-50">
                                                            入荷予定済
                                                        </Badge>
                                                    ) : (
                                                        <Badge variant="outline" className="text-purple-600 border-purple-200 bg-purple-50">
                                                            加工中
                                                        </Badge>
                                                    )}
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <div className="flex gap-1 flex-wrap justify-end">
                                                        <Button
                                                            size="sm"
                                                            className="bg-blue-600 hover:bg-blue-700 text-white text-xs px-2 h-8 flex items-center gap-1"
                                                            onClick={() => handleStartTransfer(item)}
                                                        >
                                                            <PackageCheck className="h-3 w-3" />
                                                            仕上がり移動
                                                        </Button>
                                                        <Button
                                                            size="sm"
                                                            variant="outline"
                                                            className="text-indigo-600 hover:bg-indigo-50 border-indigo-200 text-xs px-2 h-8"
                                                            onClick={() => handleArrangeShipping(item.id)}
                                                        >
                                                            出荷手配
                                                        </Button>
                                                    </div>

                                                    <Button
                                                        size="sm"
                                                        variant="ghost"
                                                        className="text-slate-500 hover:text-slate-800 h-8 w-8 p-0"
                                                        onClick={() => handleEditClick(item)}
                                                    >
                                                        編集
                                                    </Button>

                                                    <Button
                                                        size="sm"
                                                        variant="ghost"
                                                        className="text-red-500 hover:text-red-600 h-8 w-8 p-0"
                                                        onClick={() => handleDelete(item.id)}
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                </div>
                                            </div>

                                            <div className="flex items-center gap-4 text-sm text-muted-foreground bg-muted/30 p-2 rounded">
                                                <div className="flex items-center gap-1">
                                                    <CalendarClock className="h-3 w-3" />
                                                    開始: {format(new Date(item.startedAt), 'yyyy/MM/dd')}
                                                </div>
                                                <div className="flex items-center gap-1 font-medium text-foreground">
                                                    → 予定: {displayDate(item.expectedCompletion, item.termType)}
                                                </div>
                                            </div>

                                            {item.note && (
                                                <div className="text-xs text-muted-foreground">
                                                    メモ: {item.note}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            )}
                        </TabsContent>

                        <TabsContent value="add" className="mt-4 space-y-4">
                            <div className="grid gap-4 py-4">
                                {/* 数量 */}
                                <div className="grid grid-cols-4 items-center gap-4">
                                    <Label htmlFor="quantity" className="text-right">数量</Label>
                                    <CalculableInput
                                        id="quantity"
                                        value={quantity === 0 ? "" : quantity}
                                        onChange={(value) => setQuantity(Number(value) || 0)}
                                        className="col-span-3"
                                        placeholder="数量を入力"
                                    />
                                </div>

                                {/* 開始日 */}
                                <div className="grid grid-cols-4 items-center gap-4">
                                    <Label htmlFor="startedAt" className="text-right">開始日</Label>
                                    <Input
                                        id="startedAt"
                                        type="date"
                                        value={startedAt}
                                        onChange={(e) => setStartedAt(e.target.value)}
                                        className="col-span-3"
                                    />
                                </div>

                                {/* 完了予定日タイプ選択 */}
                                <div className="grid grid-cols-4 items-center gap-4">
                                    <Label className="text-right">予定日タイプ</Label>
                                    <RadioGroup
                                        defaultValue="specific"
                                        value={dateType}
                                        onValueChange={(val: 'specific' | 'vague') => setDateType(val)}
                                        className="col-span-3 flex gap-4"
                                    >
                                        <div className="flex items-center space-x-2">
                                            <RadioGroupItem value="specific" id="r1" />
                                            <Label htmlFor="r1">日付指定</Label>
                                        </div>
                                        <div className="flex items-center space-x-2">
                                            <RadioGroupItem value="vague" id="r2" />
                                            <Label htmlFor="r2">上/中/下旬</Label>
                                        </div>
                                    </RadioGroup>
                                </div>

                                {/* 完了予定日入力エリア */}
                                {dateType === 'specific' ? (
                                    <div className="grid grid-cols-4 items-center gap-4">
                                        <Label htmlFor="expected" className="text-right">仕掛完了予定日</Label>
                                        <Input
                                            id="expected"
                                            type="date"
                                            value={specificDate}
                                            onChange={(e) => setSpecificDate(e.target.value)}
                                            className="col-span-3"
                                        />
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-4 items-center gap-4">
                                        <Label className="text-right">予定時期</Label>
                                        <div className="col-span-3 flex gap-2">
                                            <Input
                                                type="month"
                                                value={vagueMonth}
                                                onChange={(e) => setVagueMonth(e.target.value)}
                                                className="w-40"
                                            />
                                            <Select value={vagueTerm} onValueChange={(val: 'early' | 'mid' | 'late') => setVagueTerm(val)}>
                                                <SelectTrigger className="w-32">
                                                    <SelectValue />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="early">上旬</SelectItem>
                                                    <SelectItem value="mid">中旬</SelectItem>
                                                    <SelectItem value="late">下旬</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        </div>
                                    </div>
                                )}

                                {/* メモ */}
                                <div className="grid grid-cols-4 items-center gap-4">
                                    <Label htmlFor="note" className="text-right">メモ</Label>
                                    <Textarea
                                        id="note"
                                        value={note}
                                        onChange={(e) => setNote(e.target.value)}
                                        className="col-span-3"
                                        placeholder="備考があれば入力"
                                    />
                                </div>
                            </div>
                            <div className="flex justify-end gap-2">
                                <Button variant="outline" onClick={() => { setActiveTab("list"); resetForm(); }}>
                                    キャンセル
                                </Button>
                                <Button onClick={handleCreateOrUpdate} disabled={actionLoading || quantity <= 0}>
                                    {actionLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4 mr-1" />}
                                    {editingWIPId ? '更新' : '登録'}
                                </Button>
                            </div>
                        </TabsContent>

                        <TabsContent value="history" className="mt-4 space-y-4">
                            {loadingCompleted ? (
                                <div className="flex justify-center py-8">
                                    <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                                </div>
                            ) : completedItems.length === 0 ? (
                                <div className="text-center py-8 text-muted-foreground">
                                    完了履歴はありません。
                                </div>
                            ) : (
                                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
                                    {completedItems.map((item) => (
                                        <div key={item.id} className="flex flex-col p-4 border rounded-lg gap-2 bg-slate-50 opacity-80">
                                            <div className="flex items-center justify-between">
                                                <div className="font-medium flex items-center gap-2">
                                                    <span className="text-lg">{item.quantity.toLocaleString()}</span>
                                                    {item.confirmationStatus === 'shipping_arranged' ? (
                                                        <Badge variant="outline" className="text-indigo-600 border-indigo-200 bg-indigo-50">
                                                            出荷手配済
                                                        </Badge>
                                                    ) : item.confirmationStatus === 'scheduled' ? (
                                                        <Badge variant="outline" className="text-emerald-600 border-emerald-200 bg-emerald-50">
                                                            入荷予定済
                                                        </Badge>
                                                    ) : (
                                                        <Badge variant="outline" className="text-slate-600 border-slate-200 bg-slate-100">
                                                            完了
                                                        </Badge>
                                                    )}
                                                </div>
                                                {item.completedAt && (
                                                    <div className="text-sm text-muted-foreground">
                                                        完了: {format(new Date(item.completedAt), 'yyyy/MM/dd')}
                                                    </div>
                                                )}
                                            </div>
                                            {item.note && (
                                                <div className="text-xs text-muted-foreground">
                                                    メモ: {item.note}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            )}
                        </TabsContent>
                    </Tabs>
                )}
            </DialogContent>
        </Dialog>
    );
}

import * as React from "react"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

export interface CalculableInputProps
    extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange'> {
    value?: number | string | null;
    onChange?: (value: number | string | null) => void;
    // If true, always formats the output as a string (useful for form states expecting string)
    stringifyOnComplete?: boolean;
}

export const CalculableInput = React.forwardRef<HTMLInputElement, CalculableInputProps>(
    ({ className, value, onChange, onBlur, onKeyDown, onFocus, stringifyOnComplete = false, ...props }, ref) => {
        // Local state to hold the user's raw string input
        const [localValue, setLocalValue] = React.useState<string>(value?.toString() ?? "");
        const [isFocused, setIsFocused] = React.useState(false);

        // Update local state if the external value changes and we are not currently editing
        React.useEffect(() => {
            if (!isFocused) {
                setLocalValue(value !== null && value !== undefined ? value.toString() : "");
            }
        }, [value, isFocused]);

        const calculateExpression = (expression: string) => {
            if (!expression.trim()) return null;

            try {
                // Remove spaces and validate allowed characters (numbers, operators, parens, decimals)
                const sanitized = expression.replace(/\s+/g, '');
                if (!/^[\d\.\+\-\*\/\(\)]+$/.test(sanitized)) {
                    return expression; // Contains invalid characters, return as is (could be empty or text)
                }

                // Extremely safe evaluation of math expressions using Function
                // Using `Function` instead of `eval` avoids some scope issues, but it's still restricted
                // Since we already regex validated to only numbers and math operators, this is safe.
                // eslint-disable-next-line no-new-func
                const result = new Function(`return ${sanitized}`)();

                if (typeof result === "number" && !isNaN(result) && isFinite(result)) {
                    // Round to avoid floating point weirdness (e.g., 0.1 + 0.2)
                    return Math.round(result * 10000000) / 10000000;
                }
            } catch (e) {
                console.warn("Invalid expression", expression);
            }
            return expression; // Fallback to raw string if calculation fails
        };

        const handleCalculateAndNotify = (val: string, forceFormat: boolean = false) => {
            const result = calculateExpression(val);

            if (result === null) {
                if (forceFormat) setLocalValue("");
                onChange?.(stringifyOnComplete ? "" : null);
            } else if (typeof result === "number") {
                const resultStr = result.toString();
                if (forceFormat) {
                    setLocalValue(resultStr);
                }
                onChange?.(stringifyOnComplete ? resultStr : result);
            } else {
                // If it didn't evaluate to a number, just return the raw string
                // We only do this on blur or enter (forceFormat) to avoid passing partial expressions upstream.
                if (forceFormat) {
                    onChange?.(result);
                }
            }
        };

        const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
            setIsFocused(false);
            handleCalculateAndNotify(localValue, true);
            onBlur?.(e);
        };

        const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
            setIsFocused(true);
            onFocus?.(e);
        };

        const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                handleCalculateAndNotify(localValue, true);
            }
            onKeyDown?.(e);
        };

        const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
            const val = e.target.value;
            setLocalValue(val);
            handleCalculateAndNotify(val, false);
        };

        return (
            <Input
                type="text" // Must be text to allow '+', '*', etc.
                className={cn("", className)}
                ref={ref}
                value={localValue}
                onChange={handleChange}
                onBlur={handleBlur}
                onFocus={handleFocus}
                onKeyDown={handleKeyDown}
                placeholder={props.placeholder || "数値または計算式 (例: 100+50)"}
                {...props}
            />
        )
    }
)
CalculableInput.displayName = "CalculableInput"

"use client";

/**
 * 画像アップロードコンポーネント
 * ブラウザ側で圧縮してからSupabase Storageにアップロード
 */

import React, { useState, useRef } from "react";
import imageCompression from "browser-image-compression";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { Loader2, Upload, X, ImageIcon } from "lucide-react";
import { cn } from "@/lib/utils";

type ImageUploadProps = {
    value?: string; // 現在の画像URL
    onChange: (url: string | null) => void; // URLが変更されたときのコールバック
    disabled?: boolean;
    bucket?: string; // Storageバケット名（デフォルト: product-images）
    folder?: string; // フォルダパス（例: products）
};

// 圧縮オプション
const compressionOptions = {
    maxSizeMB: 0.2, // 最大200KB
    maxWidthOrHeight: 800, // 最大幅/高さ
    useWebWorker: true,
    fileType: "image/webp" as const, // WebP形式で保存（軽量）
};

export function ImageUpload({
    value,
    onChange,
    disabled = false,
    bucket = "product-images",
    folder = "products",
}: ImageUploadProps): React.ReactElement {
    const [uploading, setUploading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [preview, setPreview] = useState<string | null>(value || null);
    const inputRef = useRef<HTMLInputElement>(null);

    const [isDragging, setIsDragging] = useState(false);

    // ファイル処理（共通）
    const processFile = async (file: File) => {
        // 画像ファイルかチェック
        if (!file.type.startsWith("image/")) {
            setError("画像ファイルを選択してください");
            return;
        }

        setError(null);
        setUploading(true);

        try {
            // 1. 画像を圧縮
            console.log("元のサイズ:", (file.size / 1024).toFixed(2), "KB");
            const compressedFile = await imageCompression(file, compressionOptions);
            console.log("圧縮後のサイズ:", (compressedFile.size / 1024).toFixed(2), "KB");

            // プレビュー表示
            const previewUrl = URL.createObjectURL(compressedFile);
            setPreview(previewUrl);

            // 2. Supabase Storageにアップロード
            const fileName = `${folder}/${Date.now()}_${Math.random().toString(36).substring(2, 8)}.webp`;

            const { data, error: uploadError } = await supabase.storage
                .from(bucket)
                .upload(fileName, compressedFile, {
                    contentType: "image/webp",
                    upsert: false,
                });

            if (uploadError) {
                throw new Error(uploadError.message);
            }

            // 3. 公開URLを取得
            const { data: publicUrlData } = supabase.storage
                .from(bucket)
                .getPublicUrl(data.path);

            onChange(publicUrlData.publicUrl);
        } catch (err) {
            console.error("アップロードエラー:", err);
            setError(err instanceof Error ? err.message : "アップロードに失敗しました");
            setPreview(value || null);
        } finally {
            setUploading(false);
            // input をリセット（同じファイルを再選択可能に）
            if (inputRef.current) {
                inputRef.current.value = "";
            }
        }
    };

    // ファイル選択ハンドラ
    const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>): Promise<void> => {
        const file = e.target.files?.[0];
        if (!file) return;
        await processFile(file);
    };

    // ドラッグ&ドロップハンドラ
    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (!disabled && !uploading) {
            setIsDragging(true);
        }
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);
    };

    const handleDrop = async (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);

        if (disabled || uploading) return;

        const file = e.dataTransfer.files?.[0];
        if (file) {
            await processFile(file);
        }
    };

    // 画像削除ハンドラ
    const handleRemove = (): void => {
        setPreview(null);
        onChange(null);
        setError(null);
    };

    return (
        <div className="space-y-2">
            <input
                ref={inputRef}
                type="file"
                accept="image/*"
                onChange={handleFileSelect}
                disabled={disabled || uploading}
                className="hidden"
            />

            {/* プレビューエリア */}
            {preview ? (
                <div
                    className={cn(
                        "relative inline-block transition-transform duration-200",
                        isDragging && "scale-105"
                    )}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                >
                    <img
                        src={preview}
                        alt="プレビュー"
                        className={cn(
                            "w-32 h-32 object-cover rounded-lg border",
                            isDragging && "opacity-50 blur-sm"
                        )}
                    />

                    {/* ドラッグ中のオーバーレイ */}
                    {isDragging && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/10 rounded-lg pointer-events-none">
                            <Upload className="h-8 w-8 text-primary" />
                        </div>
                    )}

                    {!disabled && !isDragging && (
                        <Button
                            type="button"
                            variant="destructive"
                            size="icon"
                            className="absolute -top-2 -right-2 h-6 w-6 rounded-full"
                            onClick={handleRemove}
                        >
                            <X className="h-3 w-3" />
                        </Button>
                    )}
                </div>
            ) : (
                <div
                    className={cn(
                        "w-32 h-32 border-2 border-dashed rounded-lg flex flex-col items-center justify-center cursor-pointer transition-all duration-200",
                        "hover:border-primary hover:bg-slate-50",
                        disabled && "opacity-50 cursor-not-allowed",
                        isDragging && "border-primary bg-blue-50 scale-105"
                    )}
                    onClick={() => !disabled && !uploading && inputRef.current?.click()}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                >
                    {uploading ? (
                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                    ) : (
                        <>
                            <Upload className={cn("h-8 w-8 mb-2 transition-colors", isDragging ? "text-primary" : "text-muted-foreground")} />
                            <span className={cn("text-xs transition-colors", isDragging ? "text-primary font-medium" : "text-muted-foreground")}>
                                {isDragging ? "ドロップして登録" : "画像を選択 / ドロップ"}
                            </span>
                        </>
                    )}
                </div>
            )}

            {/* アップロードボタン（画像がある場合は変更用） */}
            {preview && !disabled && (
                <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => inputRef.current?.click()}
                    disabled={uploading}
                >
                    {uploading ? (
                        <>
                            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                            アップロード中...
                        </>
                    ) : (
                        <>
                            <Upload className="mr-2 h-4 w-4" />
                            画像を変更
                        </>
                    )}
                </Button>
            )}

            {/* エラー表示 */}
            {error && (
                <p className="text-sm text-red-500">{error}</p>
            )}

            {/* 圧縮情報 */}
            <p className="text-xs text-muted-foreground">
                ※ 画像は自動的に圧縮されます（最大200KB, 800px）
            </p>
        </div>
    );
}

