"use client";

import { useState, useEffect, useCallback, useRef } from 'react';
import type { Product, Inventory, ApiResponse } from '@/types';
import { useAppSettings } from './use-masters';

// 商品情報付き在庫データの型
export type InventoryWithProduct = {
    productId: string;
    quantity: number;
    updatedAt: string;
    product: Product;
};

/**
 * 在庫データを取得するフック
 */
export function useInventory(options?: {
    category?: string;
    search?: string;
    lowStock?: boolean;
}): {
    inventory: InventoryWithProduct[];
    loading: boolean;
    error: string | null;
    refetch: () => void;
} {
    const [inventory, setInventory] = useState<InventoryWithProduct[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const loadedRef = useRef(false);
    const { settings } = useAppSettings();

    const fetchInventory = useCallback(async (): Promise<void> => {
        if (!loadedRef.current) setLoading(true);
        setError(null);

        try {
            const params = new URLSearchParams();
            if (options?.category && options.category !== 'all') {
                params.append('category', options.category);
            }
            if (options?.search) {
                params.append('search', options.search);
            }
            if (options?.lowStock) {
                params.append('lowStock', 'true');
            }

            const url = `/api/inventory${params.toString() ? `?${params.toString()}` : ''}`;
            const response = await fetch(url);

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const result: ApiResponse<InventoryWithProduct[]> = await response.json();

            if (result.error) {
                throw new Error(result.error);
            }

            // APIレスポンスのスネークケースをキャメルケースに変換
            const mappedData = (result.data || [])
                .filter((item: Record<string, any>) => item.product !== undefined)
                .map((item: Record<string, any>) => ({
                    productId: (item.product_id as string) || (item.productId as string) || '',
                    quantity: item.quantity as number,
                    updatedAt: (item.updated_at as string) || (item.updatedAt as string) || '',
                    product: item.product as Product
                }));
            setInventory(mappedData);
            loadedRef.current = true;
        } catch (err) {
            setError(err instanceof Error ? err.message : 'データの取得に失敗しました');
        } finally {
            setLoading(false);
        }
    }, [options?.category, options?.search, options?.lowStock]);

    useEffect(() => {
        if (settings) {
            fetchInventory();
        }
    }, [fetchInventory, settings]);

    return { inventory, loading, error, refetch: fetchInventory };
}

/**
 * ダッシュボード用統計データを取得するフック
 */
export function useDashboardStats(): {
    stats: {
        totalProducts: number;
        lowStockCount: number;
        outOfStockCount: number;
        totalInventoryValue: number;
    } | null;
    loading: boolean;
    error: string | null;
} {
    const [stats, setStats] = useState<{
        totalProducts: number;
        lowStockCount: number;
        outOfStockCount: number;
        totalInventoryValue: number;
    } | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const { settings } = useAppSettings();

    useEffect(() => {
        const fetchStats = async (): Promise<void> => {
            if (!settings) return; // Wait for settings to load

            setLoading(true);
            try {
                // 商品と在庫を取得して統計を計算
                const [productsRes, inventoryRes] = await Promise.all([
                    fetch('/api/products'),
                    fetch('/api/inventory'),
                ]);

                if (!productsRes.ok || !inventoryRes.ok) {
                    throw new Error('データの取得に失敗しました');
                }

                const products: Product[] = await productsRes.json();
                const inventoryResult: ApiResponse<InventoryWithProduct[]> = await inventoryRes.json();
                const inventory = inventoryResult.data || [];

                // 統計を計算
                const totalProducts = products.length;
                const defaultThreshold = Number(settings?.default_min_stock_alert) || 100;

                const lowStockCount = inventory.filter(i =>
                    i.quantity > 0 && i.quantity < (i.product?.minStockAlert || defaultThreshold)
                ).length;
                const outOfStockCount = inventory.filter(i => i.quantity === 0).length;
                const totalInventoryValue = inventory.reduce((sum, i) =>
                    sum + (i.quantity * (i.product?.unitPrice || 0)), 0
                );

                setStats({ totalProducts, lowStockCount, outOfStockCount, totalInventoryValue });
            } catch (err) {
                setError(err instanceof Error ? err.message : 'エラーが発生しました');
            } finally {
                setLoading(false);
            }
        };

        fetchStats();
    }, [settings]);

    return { stats, loading, error };
}

/**
 * 在庫を更新するフック
 */
export function useUpdateInventory(): {
    updateStock: (productId: string, quantity: number, type: string, note?: string) => Promise<boolean>;
    loading: boolean;
    error: string | null;
} {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const updateStock = useCallback(async (
        productId: string,
        quantity: number,
        type: string,
        note?: string
    ): Promise<boolean> => {
        setLoading(true);
        setError(null);

        try {
            const response = await fetch('/api/inventory', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ productId, quantity, type, note }),
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const result: ApiResponse<Inventory> = await response.json();

            if (result.error) {
                throw new Error(result.error);
            }

            return true;
        } catch (err) {
            setError(err instanceof Error ? err.message : '更新に失敗しました');
            return false;
        } finally {
            setLoading(false);
        }
    }, []);

    return { updateStock, loading, error };
}

"use client";

import { useState, useCallback, useRef, useEffect } from "react";

// Web Speech API interfaces
interface SpeechRecognitionResult {
    isFinal: boolean;
    [index: number]: {
        transcript: string;
    };
}

interface SpeechRecognitionResultList {
    [index: number]: SpeechRecognitionResult;
    length: number;
}

interface SpeechRecognitionEvent extends Event {
    resultIndex: number;
    results: SpeechRecognitionResultList;
}

interface SpeechRecognitionErrorEvent extends Event {
    error: string;
    message: string;
}

interface SpeechRecognition extends EventTarget {
    continuous: boolean;
    interimResults: boolean;
    lang: string;
    start: () => void;
    stop: () => void;
    abort: () => void;
    onstart: ((this: SpeechRecognition, ev: Event) => void) | null;
    onend: ((this: SpeechRecognition, ev: Event) => void) | null;
    onresult: ((this: SpeechRecognition, ev: SpeechRecognitionEvent) => void) | null;
    onerror: ((this: SpeechRecognition, ev: SpeechRecognitionErrorEvent) => void) | null;
}

interface SpeechRecognitionConstructor {
    new(): SpeechRecognition;
}

interface IWindow extends Window {
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
    SpeechRecognition?: SpeechRecognitionConstructor;
}

export function useVoiceInput(options?: {
    onResult?: (text: string) => void;
    onError?: (error: string) => void;
    lang?: string;
}) {
    const [isListening, setIsListening] = useState(false);
    const [transcript, setTranscript] = useState("");
    const [error, setError] = useState<string | null>(null);
    const recognitionRef = useRef<SpeechRecognition | null>(null);

    // Initialize recognition
    useEffect(() => {
        const { webkitSpeechRecognition, SpeechRecognition } = window as unknown as IWindow;
        const SpeechRecognitionConstructor = SpeechRecognition || webkitSpeechRecognition;

        if (SpeechRecognitionConstructor) {
            const recognition = new SpeechRecognitionConstructor();
            recognition.continuous = false; // Stop after one sentence for simple input
            recognition.interimResults = true;
            recognition.lang = options?.lang || "ja-JP";

            recognition.onstart = () => {
                setIsListening(true);
                setError(null);
            };

            recognition.onend = () => {
                setIsListening(false);
            };

            recognition.onresult = (event: SpeechRecognitionEvent) => {
                const current = event.resultIndex;
                const result = event.results[current];
                const transcriptResult = result[0].transcript;

                setTranscript(transcriptResult);

                // Final result
                if (result.isFinal && options?.onResult) {
                    options.onResult(transcriptResult);
                }
            };

            recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
                console.error("Speech recognition error", event.error);
                setError(event.error);
                setIsListening(false);
                if (options?.onError) options.onError(event.error);
            };

            recognitionRef.current = recognition;
        } else {
            // Using a timeout to move the state update out of the synchronous effect body
            setTimeout(() => {
                if (recognitionRef.current === null) {
                    setError("Browser does not support speech recognition.");
                }
            }, 0);
        }

        return () => {
            if (recognitionRef.current) {
                recognitionRef.current.abort();
            }
        };
    }, [options?.lang, options?.onResult, options?.onError]);

    const startListening = useCallback(() => {
        if (recognitionRef.current && !isListening) {
            try {
                setTranscript("");
                recognitionRef.current.start();
            } catch (e) {
                console.error(e);
            }
        }
    }, [isListening]);

    const stopListening = useCallback(() => {
        if (recognitionRef.current && isListening) {
            recognitionRef.current.stop();
        }
    }, [isListening]);

    return {
        isListening,
        transcript,
        error,
        startListening,
        stopListening,
        hasSupport: typeof window !== 'undefined' && !!((window as unknown as IWindow).SpeechRecognition || (window as unknown as IWindow).webkitSpeechRecognition)
    };
}
